\label{lem:mixing_main}
    Under \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity} and for any $Q,Q'$:
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Contraction}: with $\mathcal{T}^k_\Omega$ the $k$-th composition of the regularized Bellman operator,
        \begin{equation*}
            \|\mathcal{T}^m_\Omega(Q)-\mathcal{T}^m_\Omega(Q')\|_\mathrm{sp}\leq\left(1-\beta_m\prod_{k=1}^{m-1}\gamma_\Omega(R[\mathcal{T}_\Omega^k(Q),\mathcal{T}_\Omega^k(Q')])\right)\|Q-Q'\|_\mathrm{sp}.
        \end{equation*}
        \item \emph{Coverage}: let $(s_n,a_n)_{n\geq0}$ be a trajectory with $a_n\sim\pi_{\Omega,Q_n}(\cdot|s_n)$ and $s_{n+1}\sim p(\cdot|s_n,a_n)$, where $Q_n$ is $\mathcal{F}_{n-1}$-measurable for $\mathcal{F}_n:=\sigma(Q_0,(s_k,a_k)_{k\leq n})$. If $\gamma_1,\dots,\gamma_m\geq0$ are $\mathcal{F}_t$-measurable and $\pi_{\Omega,Q_{t+k}}\geq\gamma_k\mu$ almost surely, then almost surely 
        \begin{equation*}
            \mathbb{P}\big((s_{t+m},a_{t+m})=(s,a)\mid\mathcal{F}_t\big)\geq\beta_m\left(\prod_{k=1}^m\gamma_k\right)\eta(s,a), \quad \text{ for every } (s,a).
        \end{equation*}
        \item \emph{Bias}: the one step operator gap is: $\|\mathcal{T}_\Omega(Q)-\mathcal{T}(Q)\|_\mathrm{sp}\leq\Lambda_\Omega(\|Q\|_\mathrm{asp})$. 
        Moreover, if \@gobble{assumption:reference_policy} and~\eqref{eq:P1} hold, then for every solution $(Q^*,\rho^*)$ of $\mathcal{T}(Q^*)=Q^*+\rho^*\mathbf{1}$,
         \begin{equation*}
            \|Q^*_\Omega-Q^*\|_\mathrm{sp}\leq\frac{m\,\Lambda_\Omega(R^*)}{\beta_m\gamma_\Omega(R^*)^{m-1}},\qquad R^*:=\max\Big\{\|Q^*_\Omega\|_\mathrm{asp},\max_{0\leq k<m}\|\mathcal{T}^k_\Omega(Q^*)\|_\mathrm{asp}\Big\},
        \end{equation*}
        and, if $|\mathcal{S}|\geq2$ and all the $\Omega_s$ have the same minimum $\underline{\Omega}$, as divergences to $\mu$ do with $\underline{\Omega}=0$,
        \begin{equation*}
            -\Lambda_\Omega(\|Q^*\|_\mathrm{asp})\leq\rho^*_\Omega-\rho^*+\tau\underline{\Omega}\leq0.
        \end{equation*}
    \end{enumerate}

\label{cor:q-iteration}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy} and~\eqref{eq:P1} hold. Then $(\|Q_t-Q_\Omega^*\|_\mathrm{sp})_{t\geq0}$ is non-increasing and, for every $t\geq0$,
    \begin{equation}
        \label{eq:q-iteration-rate}
        \|Q_{t+m} - Q^*_\Omega \|_\mathrm{sp} \leq\Big(1-\beta_m\,\gamma_\Omega\big(\|Q^*_\Omega\|_\mathrm{asp}+ \|Q_{t} - Q^*_\Omega \|_\mathrm{sp} \big)^{m-1}\Big) \|Q_{t} - Q^*_\Omega \|_\mathrm{sp}.
    \end{equation}
    Consequently, for $\varepsilon\in(0,e_0)$, $\|Q_T-Q_\Omega^*\|_\mathrm{sp}\leq\varepsilon$ for every $T\geq m\lceil\tilde{\beta}^{-1}\log(e_0/\varepsilon)\rceil$, i.e.\ after $O\big(|\mathcal{S}|^2|\mathcal{A}|\,m\,\tilde{\beta}^{-1}\log(e_0/\varepsilon)\big)$ model queries, one query being an evaluation of $p(s'|s,a)$.

\label{thm:sync-stoch-main}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy} and~\eqref{eq:P1} hold, and set 
    $\alpha(u):= (\tilde\beta^2u^2)(9m(2+\tilde\beta)^2(1+9m)^2\bar w^2\iota)^{-1}$ 
    for $u>0$. Run \@gobble{alg:synchronous_regularized_q_learning} for $T$ iterations with a constant step size $\alpha\leq\alpha(e_0)$. Then, with probability at least $1-\delta$, $\sup_{t\leq T}\|Q_t-Q^*_\Omega\|_\mathrm{sp}\leq2e_0$ and
    \begin{equation}
        \label{eq:sync-stoch-main}
        \|Q_T-Q^*_\Omega\|_\mathrm{sp}\leq\frac{(1-\tilde\beta/2)^{\frac{2\alpha T}{9m}}}{1-\tilde\beta/2}\,\|Q_0-Q_\Omega^*\|_\mathrm{sp}+\frac{3(2+\tilde\beta)(1+9m)}{\tilde\beta}\,\bar w\sqrt{m\alpha\iota}.
    \end{equation}
    In particular, for $\varepsilon\in(0,e_0)$, the choices $\alpha=\alpha(\varepsilon/2)$ and $T\geq\frac{9m}{\alpha\tilde\beta}\log\left(\frac{2e_0}{(1-\tilde\beta/2)\varepsilon}\right)$ give $\|Q_T-Q^*_\Omega\|_\mathrm{sp}\leq\varepsilon$, i.e.\ $\tilde O\big(|\mathcal{S}||\mathcal{A}|\,m^4\bar w^2/(\tilde\beta^3\varepsilon^2)\big)$ sampled transitions.

\label{thm:epoch-main-body}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy} and~\eqref{eq:P1} hold, and set $B(u):=\frac{8m^2\bar w^2\iota}{(\tilde\beta u)^2}$ for $u>0$. Run \@gobble{alg:epoch_regularized_q_learning} with $\alpha_j\equiv1$ and a constant batch size $B\geq B(e_0)$, and let $J(T)$ be the number of epochs completed within $T$ transitions. Then, with probability at least $1-\delta$, $\sup_{j\leq J(T)}\|Q_j-Q^*_\Omega\|_\mathrm{sp}\leq2e_0$, each epoch completed within the budget lasts at most $L:=m\big\lceil(\sqrt B+\sqrt\iota)^2/(\bar\gamma\tilde\beta\eta_{\min})\big\rceil+1$ transitions, so that $J(T)\geq\lfloor T/L\rfloor$, and
    \begin{equation}
        \label{eq:epoch-main-bound}
        \|Q_{J(T)}-Q^*_\Omega\|_\mathrm{sp}\leq(1-\tilde\beta)^{\lfloor J(T)/m\rfloor}\|Q_0-Q_\Omega^*\|_\mathrm{sp}+\frac{2\sqrt2\,m\,\bar w}{\tilde\beta}\sqrt{\frac{\iota}{B}}.
    \end{equation}
    In particular, for $\varepsilon\in(0,e_0)$, the choices $B=\lceil B(\varepsilon/2)\rceil$ and $T\geq mL\lceil\tilde\beta^{-1}\log(2e_0/\varepsilon)\rceil$ give $\|Q_{J(T)}-Q^*_\Omega\|_\mathrm{sp}\leq\varepsilon$, i.e.\ 
    $\tilde O\big(m^4\bar w^2/(\tilde\beta^4\bar\gamma\eta_{\min}\varepsilon^2)\big)$ 
    sampled transitions.

\label{prop:minimal_horizon}
    Under \@gobble{assumption:m-step-mixing}, let $e(X):=\min\{k\geq0\mid XG^k=\mathcal{S}\}$ for nonempty $X\subseteq\mathcal{S}$. The smallest horizon at which \@gobble{assumption:m-step-mixing} holds is
    \begin{equation*}
        m^*=1+\max_{(s,a)\in\mathcal{S}\times\mathcal{A}}e\big(\mathrm{supp}\,p(\cdot|s,a)\big),
    \end{equation*}
    and $\mathrm{ex}(G)\leq m^*\leq\mathrm{ex}(G)+1\leq(|\mathcal{S}|-1)^2+2$.

\label{lem:self-bounding}
    Let $(Z_i)_{i=1}^{B}$ be adapted to a filtration $(\mathcal{G}_i)$ with $Z_i\in[0,b]$ almost surely. Let $S:=\sum_{i=1}^B Z_i$ and $\bar{S}:=\sum_{i=1}^B\mathbb{E}[Z_i\mid\mathcal{G}_{i-1}]$. For any deterministic $a>0$ and $c\in(0,a)$,
    \begin{equation}
        \mathbb{P}\big(S<c,\ \bar{S}\geq a\big) \leq\exp\Big(-\frac{1}{b}\Big(a-c-c\log\frac{a}{c}\Big)\Big)\label{eq:exact-chernoff}
    \end{equation}

\label{lem:azuma_range}
    Let $(M_k)_{0\leq k\leq n}$ be a martingale with $M_0=0$, adapted to $(\mathcal{F}_k)$, such that for each $k$ the increment $M_k-M_{k-1}$ lies a.s.\ in an interval $[\mathcal{L}_k,\mathcal{L}_k+c_k]$ with $\mathcal{L}_k$ $\mathcal{F}_{k-1}$-measurable and $c_k>0$ deterministic. Then for every $u>0$,
    \begin{equation*}
        \mathbb{P}\left(\max_{0\leq k\leq n}|M_k|\geq u\right)\leq2\exp\left(-\frac{2u^2}{\sum_{k=1}^nc_k^2}\right).
    \end{equation*}

\label{def:tv_norm}
    The total-variation distance between two probability distributions $\phi, \phi' \in \Delta(\mathcal{X})$ is defined as:
    \begin{equation}
        \|\phi - \phi'\|_{\mathrm{TV}} = \frac{1}{2}\sum_{x\in \mathcal{X}} |\phi(x) - \phi'(x)|.
    \end{equation}

\label{def:dobrushin}
    The Dobrushin coefficient of a row-stochastic matrix $P\in\mathbb{R}^{\mathcal{X}\times\mathcal{Y}}$ is defined as:
    \begin{equation}
        \alpha(P) = \sup_{\phi\neq\phi' \in \Delta(\mathcal{X})}\frac{\|\phi P -\phi' P\|_{\mathrm{TV}}}{\|\phi -\phi'\|_{\mathrm{TV}}}=\sup_{x,x'\in\mathcal{X}}\|P(\cdot|x)-P(\cdot|x')\|_{\mathrm{TV}},
    \end{equation} 
    the equality of the two expressions being due to \citet{dobrushin1956central}.

\label{def:operator_span_seminorm}
    The operator span seminorm of a linear operator $A:\mathbb{R}^p \to \mathbb{R}^q$ is defined as:
    \begin{equation}
        \|A\|_{\mathrm{sp},\mathrm{op}} = \sup_{\|x\|_{\mathrm{sp}}\leq 1}\|Ax\|_{\mathrm{sp}}\in\mathbb{R}^+\cup\{+\infty\}.
    \end{equation}

\label{lem:spop}
    Let $A:\mathbb{R}^{p}\to\mathbb{R}^{q}$ be linear. The following two conditions are equivalent:
    \begin{enumerate}[label=(\roman*)]
        \item $\|A\|_{\mathrm{sp},\mathrm{op}}<+\infty$;
        \item $A\cdot\mathrm{Ker}\|\cdot\|_{\mathrm{sp}}\subseteq\mathrm{Ker}\|\cdot\|_{\mathrm{sp}}$, i.e. $A\mathbf{1}\in\mathbb{R}\mathbf{1}$, i.e. $A$ has constant row sums.
    \end{enumerate}
    When they hold, for every $f\in\mathbb{R}^{p}$ and every linear map $B:\mathbb{R}^{p'}\to\mathbb{R}^{p}$ satisfying (ii),
    \begin{equation}
        \label{eq:sub-multiplicativity}
        \|Af\|_\mathrm{sp}\leq\|A\|_{\mathrm{sp},\mathrm{op}}\|f\|_\mathrm{sp}, \qquad \|AB\|_{\mathrm{sp},\mathrm{op}}\leq\|A\|_{\mathrm{sp},\mathrm{op}}\|B\|_{\mathrm{sp},\mathrm{op}}.
    \end{equation}

\label{prop:mvi-span}
    Let $U\subseteq\mathbb{R}^p$ be open, let $\Phi:U\to\mathbb{R}^q$, and let $Q,Q'\in U$ be such that $[Q',Q]\subseteq U$. Assume:
    \begin{enumerate}
        \item[(H1)] $\Phi$ is differentiable at every point of $[Q',Q]$;
        \item[(H2)] for every $t\in[0,1]$, the Jacobian $D\Phi(Q(t))$ has constant row sums, i.e.\ $D\Phi(Q(t))\mathbf{1}\in\mathbb{R}\mathbf{1}$.
    \end{enumerate}
    Then
    \begin{equation}
        \label{eq:mvi-span}
        \left\|\Phi(Q)-\Phi(Q')\right\|_\mathrm{sp}\ \leq\ \sup_{t\in(0,1)}\left\|D\Phi(Q(t))\right\|_{\mathrm{sp},\mathrm{op}}\,\|Q-Q'\|_\mathrm{sp},
    \end{equation}
    and in particular with the supremum taken over the closed segment.

\label{cor:avg}
    If moreover $\Phi$ is $\mathcal{C}^1$ on a neighborhood of $[Q',Q]$, then
    \begin{equation*}
        \Phi(Q)-\Phi(Q')=\bar{A}\,(Q-Q'),\qquad\bar{A}:=\int_0^1D\Phi(Q(t))\,\mathrm{d}t.
    \end{equation*}
    $\bar{A}$ is the average of the Jacobians of $\Phi$ along the segment; it has constant row sums and $\|\bar{A}\|_{\mathrm{sp},\mathrm{op}}\leq\sup_{t\in(0,1)}\|D\Phi(Q(t))\|_{\mathrm{sp},\mathrm{op}}$.

\label{rem:bounded_modulus}
    Let $\overline{\Omega}:=\max_{s\in\mathcal{S}}\max_{a\in\mathcal{A}}\Omega_s(\delta_a)$, $\underline{\Omega}=\min_s\underline{\Omega}_s$ and $\Delta_\Omega:=\overline{\Omega}-\underline{\Omega}$. If $\overline{\Omega}<+\infty$, i.e.\ if every Dirac lies in the effective domain, then \@gobble{lem:omega_star_props}.(ii) applied state-wise with $L_{\Omega_s}=\underline{\Omega}$ and $U_{\Omega_s}=\max_a\Omega_s(\delta_a)$ gives $\Lambda_\Omega(R)\leq\tau\Delta_\Omega$ for every $R$: the modulus is bounded by a radius-independent constant and all the bounds below reduce to their constant counterparts.

    The $\alpha$-divergences with $\alpha\leq0$, including the forward KL, and the floor-wrapped regularizers of \@gobble{def:floor_wrapped} exclude every Dirac from their effective domain, so $\overline{\Omega}=+\infty$, while $\Lambda_\Omega(R)$ stays finite (\@gobble{thm:alpha}.(v) and \@gobble{lem:floor_wrapped_props}.(v)); this is what makes the radius-dependent form necessary.

\label{lem:mixing-properties-of-regularization}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity} hold and let $Q,Q'\in\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$. Then:
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Average-path factorization of the conjugate and of the operator}: for every $s\in\mathcal{S}$, $\Omega^*(Q)(s)-\Omega^*(Q')(s)=\langle\bar{\pi}_{\Omega,[Q,Q']}(\cdot|s),Q_s-Q'_s\rangle$ and $\mathcal{T}_\Omega(Q)-\mathcal{T}_\Omega(Q')=K_{\bar{\pi}_{\Omega,[Q,Q']}}(Q-Q')$. 
        \item \emph{Domination of the average-path policy}: $\bar{\pi}_{\Omega,[Q,Q']}(a|s)\geq\gamma_\Omega(R[Q,Q'])\,\mu(a|s)$ for every $(s,a)\in\mathcal{S}\times\mathcal{A}$.
        \item \emph{$m$-step minorization}: if $\pi_1,\dots,\pi_m$ are policies with $\pi_k\geq\gamma_k\mu$ for $k\in\llbracket1,m\rrbracket$, the $m$-step kernel $K_{\pi_1:\pi_m}:=K_{\pi_1}\cdots K_{\pi_m}$ satisfies
        \begin{equation*}
            K_{\pi_1:\pi_m}(s',a'|s,a)\geq\beta_m\left(\prod_{k=1}^{m}\gamma_k\right)\eta(s',a'),\qquad\forall(s,a),(s',a')\in\mathcal{S}\times\mathcal{A}.
        \end{equation*}
        \item \emph{Radius-dependent $m$-step contraction}: 
        \begin{equation*}
            \left\|\mathcal{T}^m_\Omega(Q)-\mathcal{T}^m_\Omega(Q')\right\|_\mathrm{sp}\leq\left(1-\beta_m\prod_{k=1}^{m-1}\gamma_\Omega\left(R[\mathcal{T}^{k}_{\Omega}(Q), \mathcal{T}^{k}_{\Omega}(Q')]\right)\right)\|Q-Q'\|_\mathrm{sp}.
        \end{equation*}
        \item \emph{State-action coverage}: let $(Q_n)_{n\geq0}$ be $Q$-functions and $(s_n,a_n)_{n\geq0}$ a trajectory with $a_n\sim\pi_{\Omega,Q_n}(\cdot|s_n)$ and $s_{n+1}\sim p(\cdot|s_n,a_n)$; let $\mathcal{F}_n:=\sigma(Q_0,(s_0,a_0),\dots,(s_n,a_n))$ and assume that $Q_n$ is $\mathcal{F}_{n-1}$-measurable for $n\geq1$. If $t\geq0$ and $\gamma_1,\dots,\gamma_m$ are non-negative $\mathcal{F}_t$-measurable random variables with $\pi_{\Omega,Q_{t+k}}\geq\gamma_k\mu$ almost surely for $k\in\llbracket1,m\rrbracket$, then almost surely
        \begin{equation*}
            \mathbb{P}\big((s_{t+m},a_{t+m})=(s,a)\mid\mathcal{F}_t\big)\geq\beta_m\left(\prod_{k=1}^{m}\gamma_k\right)\eta(s,a),\qquad\forall(s,a)\in\mathcal{S}\times\mathcal{A}.
        \end{equation*}
        \item \emph{One-step operator gap}: for every $Q\in\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$,
        \begin{equation*}
            \|\mathcal{T}_\Omega(Q)-\mathcal{T}(Q)\|_\mathrm{sp}\leq\alpha(P)\,\Lambda_\Omega\big(\|Q\|_\mathrm{asp}\big)\leq\Lambda_\Omega\big(\|Q\|_\mathrm{asp}\big),
        \end{equation*}
        where $\alpha(P)$ is the Dobrushin coefficient (\@gobble{def:dobrushin}) of the rectangular matrix $(p(s'|s,a))_{(s,a),s'}$. In particular, under the assumptions of \@gobble{rem:bounded_modulus}, $\|\mathcal{T}_\Omega(Q)-\mathcal{T}(Q)\|_\mathrm{sp}\leq\alpha(P)\tau\Delta_\Omega\leq\tau\Delta_\Omega$ uniformly in $Q$.
    \end{enumerate}

Throughout the proof we write $\bar{\pi}=\bar{\pi}_{\Omega,[Q,Q']}$, $\gamma_k$ for the domination coefficients of each item and $\eta(s',a')=\nu(s')\mu(a'|s')$ for the minorizing measure of \@gobble{assumption:m-step-mixing}. Points (i), (ii), (iv) and (v) use $\tau>0$ through \@gobble{lem:omega_star_props}.(i), whereas (iii) requires no regularity at all and (vi) only uses \@gobble{assumption:convex-analytic-regularity} through the finiteness of $\Lambda_\Omega$ (\@gobble{lem:modulus_properties}).

    \emph{(i)}. Let $g(t):=\Omega^*(Q(t))(s)$ for $t\in[0,1]$. Since $\Omega^*(Q)(s)$ depends on $Q$ only through $Q_s$, \@gobble{lem:omega_star_props}.(i) and the chain rule give that $g$ is continuously differentiable, with $g'(t)=\langle\pi_{\Omega,Q(t)}(\cdot|s),Q_s-Q'_s\rangle$. The fundamental theorem of calculus and the linearity of the inner product then give
    \begin{equation}
        \label{eq:value-factorization}
        \Omega^*(Q)(s)-\Omega^*(Q')(s)=g(1)-g(0)=\int_0^1\langle\pi_{\Omega,Q(t)}(\cdot|s),Q_s-Q'_s\rangle\,\mathrm{d}t=\langle\bar{\pi}(\cdot|s),Q_s-Q'_s\rangle,
    \end{equation}
    which is the first equality. Since $\mathcal{T}_\Omega=r+P\,\Omega^*$, the reward terms cancel and applying~\eqref{eq:value-factorization} at each next state $s'\in\mathcal{S}$ gives, for every $(s,a)\in\mathcal{S}\times\mathcal{A}$,
    \begin{equation*}
    \begin{aligned}
        \mathcal{T}_\Omega(Q)(s,a)-\mathcal{T}_\Omega(Q')(s,a)
        &=\sum_{s'}p(s'|s,a)\big(\Omega^*(Q)(s')-\Omega^*(Q')(s')\big)\\
        &=\sum_{s',a'}p(s'|s,a)\,\bar{\pi}(a'|s')\,(Q-Q')(s',a')
        =\big(K_{\bar{\pi}}(Q-Q')\big)(s,a),
    \end{aligned}
    \end{equation*}
    which is the second equality.

    \emph{(ii)}. By \@gobble{def:mixing_objects}.(ii), $\|Q(t)\|_\mathrm{asp}\leq R[Q,Q']$ for all $t\in[0,1]$, and \@gobble{def:mixing_objects}.(iii) applied with $R=R[Q,Q']$ then gives $\pi_{\Omega,Q(t)}(a|s) \geq \gamma_\Omega(R[Q,Q'])\mu(a|s)$ for all $(s,a)$ and all $t\in[0,1]$, uniformly in $t$. Integrating this inequality against the uniform measure on $[0,1]$ and using \@gobble{def:mixing_objects}.(i) yields $\bar{\pi}(a|s) = \int_0^1 \pi_{\Omega,Q(t)}(a|s)\,\mathrm{d}t \geq \gamma_\Omega(R[Q,Q'])\mu(a|s)$, which is the claim.

    \emph{(iii)}. Set $\Gamma_{1:m}=\prod_{k=1}^m\gamma_k$. First, for any policy $\pi$ with $\pi(a|s)\geq\gamma\mu(a|s)$ we have the transport inequality $P_\pi(s'|s) = \sum_a \pi(a|s)p(s'|s,a) \geq \gamma\sum_a\mu(a|s)p(s'|s,a) = \gamma P_\mu(s'|s)$. 
    By definition of $K_{\pi_1:\pi_m}=K_{\pi_1}\cdots K_{\pi_m}$ and \@gobble{convention:product_order}, the first action is the one supplied by the conditioning, the intermediate actions are drawn from $\pi_1,\dots,\pi_{m-1}$ and the terminal action from $\pi_m$:
    \begin{equation}
        \label{eq:mstep_sa_kernel}
        K_{\pi_1:\pi_m}(s',a'|s,a) = \pi_m(a'|s') \sum_{s_1,\dots,s_{m-1}} p(s_1|s,a)\prod_{k=1}^{m-1} P_{\pi_k}(s_{k+1}|s_k),
    \end{equation}
    with $s_m=s'$, and since all factors are non-negative, the bounds multiply: applying the transport inequality to the $m-1$ intermediate factors and the domination hypothesis to the terminal factor $\pi_m(a'|s')\geq\gamma_m\mu(a'|s')$ gives
    \begin{align*}
        K_{\pi_1:\pi_m}(s',a'|s,a) &\geq \Gamma_{1:m}\,\mu(a'|s') \sum_{s_1,\dots,s_{m-1}} p(s_1|s,a)\prod_{k=1}^{m-1} P_\mu(s_{k+1}|s_k)\\
        &= \Gamma_{1:m}\,\mu(a'|s') \sum_{s_1} p(s_1|s,a)\, P_\mu^{m-1}(s'|s_1)\\
        &= \Gamma_{1:m}\,\mu(a'|s')\, K_\mu^m(s'|s,a)\\
        &\geq \Gamma_{1:m}\,\beta_m\,\nu(s')\mu(a'|s') = \Gamma_{1:m}\,\beta_m\,\eta(s',a'),
    \end{align*}
    the second-to-last line by the definition $K^m_\mu(s'|s,a)=\sum_{s_1}p(s_1|s,a)P_\mu^{m-1}(s'|s_1)$ and the last by \@gobble{assumption:m-step-mixing}.

    \emph{(iv)}. For $k\in\llbracket 0,m-1\rrbracket$ write $Q_k:=\mathcal{T}_\Omega^k(Q)$, $Q_k':=\mathcal{T}_\Omega^k(Q')$, $R_k:=R[Q_k,Q_k']$, $\bar{\pi}^{(k)} = \bar{\pi}_{\Omega,[Q_k,Q_k']}$ and $\gamma_k = \gamma_\Omega(R_k)$. (i) applied at level $k$ gives the one-step identity $Q_{k+1}-Q_{k+1}' = \mathcal{T}_\Omega(Q_k)-\mathcal{T}_\Omega(Q_k') = K_{\bar{\pi}^{(k)}}(Q_k-Q_k')$, where $K_{\bar{\pi}^{(k)}}$ is a row-stochastic state-action kernel. Iterating this identity from $k=m-1$ down to $k=0$, we obtain
    \begin{equation*}
        \mathcal{T}^m_\Omega(Q)-\mathcal{T}^m_\Omega(Q') = Q_m - Q_m' = K^{(m)}_{Q,Q'}(Q-Q'), \qquad K^{(m)}_{Q,Q'} := K_{\bar{\pi}^{(m-1)}}K_{\bar{\pi}^{(m-2)}}\cdots K_{\bar{\pi}^{(0)}}.
    \end{equation*}
    Following \@gobble{convention:product_order}, $K^{(m)}_{Q,Q'}$ is exactly the $m$-step state-action kernel $K_{\bar{\pi}^{(m-1)}:\bar{\pi}^{(0)}}$ associated with the sequence of policies $\bar{\pi}^{(m-1)},\dots,\bar{\pi}^{(0)}$. By (ii), each of them satisfies $\bar{\pi}^{(k)}\geq\gamma_k\mu$, so (iii) applies and gives the Doeblin condition $K^{(m)}_{Q,Q'}(s',a'|s,a) \geq \beta_m\left(\prod_{k=0}^{m-1}\gamma_k\right)\eta(s',a')$. \@gobble{lem:terminal_action}, applied with $\pi_1=\bar\pi^{(m-1)},\dots,\pi_m=\bar\pi^{(0)}$, gives $\alpha\big(K^{(m)}_{Q,Q'}\big)\leq1-\beta_m\prod_{k=1}^{m-1}\gamma_\Omega(R_k)$, and by \@gobble{lem:row-stochastic-span}, $\|K^{(m)}_{Q,Q'}\|_{\mathrm{sp},\mathrm{op}} = \alpha\left(K^{(m)}_{Q,Q'}\right)$. Therefore
    \begin{equation*}
        \left\|\mathcal{T}^m_\Omega(Q)-\mathcal{T}^m_\Omega(Q')\right\|_\mathrm{sp} = \left\|K^{(m)}_{Q,Q'}(Q-Q')\right\|_\mathrm{sp} \leq \left(1-\beta_m\prod_{k=1}^{m-1}\gamma_\Omega(R_k)\right)\|Q-Q'\|_\mathrm{sp}.
    \end{equation*}

    \emph{(v)}. Fix $t\geq 0$ and $(s,a)\in\mathcal{S}\times\mathcal{A}$. For $j\in\llbracket0,m\rrbracket$, let $\Gamma_j:=\prod_{k=j+1}^{m}\gamma_k$, which is non-negative and $\mathcal{F}_t$-measurable, hence $\mathcal{F}_{t+j}$-measurable. We prove by backward induction on $j$ that, a.s.,
    \begin{equation*}
        \mathbb{E}\left[\mathbb{1}_{\{(s_{t+m},a_{t+m})=(s,a)\}}\ \middle|\ \mathcal{F}_{t+j}\right]\ \geq\ \Gamma_j\,K^{m-j}_\mu\big(s,a\mid s_{t+j},a_{t+j}\big).
    \end{equation*}
    The case $j=m$ is an equality. Assume the claim at $j+1$. Conditionally on $\mathcal{F}_{t+j}$, $s_{t+j+1}\sim p(\cdot|s_{t+j},a_{t+j})$ and $a_{t+j+1}\sim\pi_{\Omega,Q_{t+j+1}}(\cdot|s_{t+j+1})$, where $Q_{t+j+1}$ is $\mathcal{F}_{t+j}$-measurable. By the tower property, the induction hypothesis and the $\mathcal{F}_{t+j}$-measurability of $\Gamma_{j+1}$, the left-hand side at level $j$ is therefore at least
    \begin{align*}
        &\Gamma_{j+1}\sum_{s'}p(s'|s_{t+j},a_{t+j})\sum_{a'}\pi_{\Omega,Q_{t+j+1}}(a'|s')\,K^{m-j-1}_\mu\big(s,a\mid s',a'\big)\\
        &\qquad\geq \Gamma_{j+1}\gamma_{j+1}\sum_{s',a'}K_\mu(s',a'|s_{t+j},a_{t+j})\,K^{m-j-1}_\mu\big(s,a\mid s',a'\big)
        = \Gamma_j\,K^{m-j}_\mu\big(s,a\mid s_{t+j},a_{t+j}\big),
    \end{align*}
    the inequality by the domination hypothesis and the non-negativity of $\Gamma_{j+1}$ and of $K^{m-j-1}_\mu$. Taking $j=0$ and using that the $m$-step state-action kernel of $\mu$ satisfies $K^m_\mu(s',a'|s,a)=K^m_\mu(s'|s,a)\mu(a'|s')\geq\beta_m\nu(s')\mu(a'|s')=\beta_m\eta(s',a')$ by \@gobble{assumption:m-step-mixing} gives the claim.

    \emph{(vi)}. \@gobble{def:mixing_objects}.(iv) applied with $R=\|Q\|_\mathrm{asp}$ immediately gives $\|g_Q\|_{\mathcal{S},\mathrm{sp}}\leq\Lambda_\Omega(\|Q\|_\mathrm{asp})$. The two operators $\mathcal{T}_\Omega$ and $T$ share the reward term and differ only through the state-value function, so for all $(s,a)$,
    \begin{equation*}
        \mathcal{T}_\Omega(Q)(s,a)-\mathcal{T}(Q)(s,a) = \sum_{s'}p(s'|s,a)\left(\Omega^*(Q)(s')-\max_{a'}Q(s',a')\right) = (Pg_Q)(s,a).
    \end{equation*}
    \@gobble{lem:row-stochastic-span} gives $\|Pg_Q\|_\mathrm{sp}\leq\alpha(P)\|g_Q\|_{\mathcal{S},\mathrm{sp}}$, so $\|\mathcal{T}_\Omega(Q)-\mathcal{T}(Q)\|_\mathrm{sp}\leq\alpha(P)\Lambda_\Omega(\|Q\|_\mathrm{asp})$. The second inequality follows from $\alpha(P)\leq1$, and the last claim from \@gobble{rem:bounded_modulus}.

\label{rem:tail_only}
    Let $\pi_1,\dots,\pi_M$ with $M\geq m$ be given, and assume that only the last $m$ of them are known to be regularized, say $\pi_k\geq\gamma_k\mu$ for $k\in\llbracket M-m+1,M\rrbracket$, with $\Gamma_{M-m+1:M}:=\prod_{k=M-m+1}^{M}\gamma_k$. Then \@gobble{lem:mixing-properties-of-regularization}.(iii) still holds for the full $M$-step kernel, with the same parameter $\Gamma_{M-m+1:M}\beta_m$ and the same minorizing measure $\eta$.

    Writing $K_{\mathrm{head}}:=K_{\pi_1:\pi_{M-m}}$ for the kernel of the first $M-m$ steps and $K_{\mathrm{tail}}:=K_{\pi_{M-m+1}:\pi_M}$ for that of the last $m$ ones, we have, consistently with \@gobble{convention:product_order},
    \begin{equation*}
        K_{\pi_1:\pi_M} = K_{\mathrm{head}}K_{\mathrm{tail}}, \qquad\text{i.e.}\qquad K_{\pi_1:\pi_M}(s',a'|s,a) = \sum_{(\tilde s,\tilde a)} K_{\mathrm{head}}(\tilde s,\tilde a|s,a)K_{\mathrm{tail}}(s',a'|\tilde s,\tilde a).
    \end{equation*}
    \@gobble{lem:mixing-properties-of-regularization}.(iii) applies to $K_{\mathrm{tail}}$ and gives $K_{\mathrm{tail}}(s',a'|\tilde s,\tilde a)\geq\Gamma_{M-m+1:M}\beta_m\,\eta(s',a')$ uniformly in the starting pair $(\tilde s,\tilde a)$; the head, which requires no regularization, only contributes a factor $1$ by row-stochasticity:
    \begin{equation*}
        K_{\pi_1:\pi_M}(s',a'|s,a) \geq \Gamma_{M-m+1:M}\beta_m\eta(s',a') \sum_{(\tilde s,\tilde a)} K_{\mathrm{head}}(\tilde s,\tilde a|s,a) = \Gamma_{M-m+1:M}\beta_m\eta(s',a').
    \end{equation*}

    The same holds for the coverage bound of \@gobble{lem:mixing-properties-of-regularization}.(v): if its domination hypothesis holds only for $k\in\llbracket M-m+1,M\rrbracket$, then, almost surely,
    \begin{equation*}
        \mathbb{P}\big((s_{t+M},a_{t+M})=(s,a)\mid\mathcal{F}_t\big)\geq\Gamma_{M-m+1:M}\beta_m\,\eta(s,a).
    \end{equation*}
    Indeed, \@gobble{lem:mixing-properties-of-regularization}.(v) applied at time $t+M-m$ gives this lower bound for the probability conditional on $\mathcal{F}_{t+M-m}$, and the tower property transfers it to $\mathcal{F}_t$, the bound being deterministic: the conditional expectation plays the role of the row-stochastic head. Since the proof of (v) only uses the steps after time $t+M-m$, the actions of the head may moreover follow any adapted rule.

\label{thm:regularized_fixed_point}
    Under \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy}, there exist $Q_\Omega^*\in\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$ and $\rho_\Omega^*\in\mathbb{R}$ such that $\mathcal{T}_\Omega(Q_\Omega^*)=Q_\Omega^*+\rho_\Omega^*\mathbf{1}$, with
    \begin{equation*}
        \left\|Q^*_\Omega\right\|_\mathrm{sp}\leq\|r\|_\mathrm{sp}+\frac{4mR_{\max}}{\beta_m\nu_{\min}}, \qquad \left\lvert\rho^*_\Omega\right\rvert\leq2R_{\max},
    \end{equation*}
    where $\nu_{\min}=\min_s\nu(s)>0$ and $R_{\max}=\|r\|_\infty+\tau\max_s\max\{\lvert\underline{\Omega}_s\rvert,\lvert\Omega_s(\mu_s)\rvert\}$, both finite under \@gobble{assumption:reference_policy}.
    Moreover $\rho^*_\Omega$ is unique and is the optimal regularized gain (\@gobble{prop:uniqueness_gain,prop:gain_interpretation}), and under~\eqref{eq:P1} $Q^*_\Omega$ is unique up to an additive constant (\@gobble{prop:uniqueness_fixed_point}).

\label{lem:discounted_fixed_point}
    Let $\lambda\in(0,1)$ and $\mathcal{T}^\lambda_\Omega(Q):=r+\lambda P\,\Omega^*(Q)$.
    Then $\mathcal{T}^\lambda_\Omega$ is a $\lambda$-contraction for $\|\cdot\|_\infty$ with unique fixed point $Q^\lambda$, and $V^\lambda:=\Omega^*(Q^\lambda)$ satisfies
    \begin{equation}
        \label{eq:discounted_Q}
        Q^\lambda(s,a)=r(s,a)+\lambda\sum_{s'}p(s'|s,a)\,V^\lambda(s'),
        \qquad
        V^\lambda=\mathcal{T}^\lambda_\Omega V^\lambda .
    \end{equation}
    The operator $\mathcal{T}^\lambda_\Omega$ is monotone and $\lambda$-translation equivariant, and the maximum defining $\mathcal{T}^\lambda_\Omega V^\lambda$ is attained at the unique $\pi^\lambda:=\pi_{\Omega,Q^\lambda}=\nabla\Omega^*(Q^\lambda)$; in particular $V^\lambda=\mathcal{E}^\lambda_{\pi^\lambda}V^\lambda\geq\mathcal{E}^\lambda_{\pi}V^\lambda$ for every admissible $\pi$.

We have $\mathcal{T}^\lambda_\Omega(Q)-\mathcal{T}^\lambda_\Omega(Q')=\lambda P(\Omega^*(Q)-\Omega^*(Q'))$ with $P$ row-stochastic and $\Omega^*$ non-expansive for $\|\cdot\|_\infty$ (\@gobble{lem:omega_star_props}.(v)), so $\mathcal{T}^\lambda_\Omega$ is a $\lambda$-contraction on the complete space $(\mathbb{R}^{\mathcal{S}\times\mathcal{A}},\|\cdot\|_\infty)$ and Banach's theorem applies; this is the regularized discounted operator of~\citep[Thm.~1]{geist2019theory}.
    Substituting the first identity of~\eqref{eq:discounted_Q} into the definition of $\Omega^*$ gives, for every $s$,
    \begin{equation}
        \label{eq:discounted_ACOE}
        V^\lambda(s)=\max_{\pi_s\in\mathrm{dom}(\Omega_s)}\left\{\tilde{r}_\pi(s)+\lambda\left(P_\pi V^\lambda\right)(s)\right\}
        =\left(\mathcal{T}^\lambda_\Omega V^\lambda\right)(s),
    \end{equation}
    the maximizer being unique and equal to $\nabla\Omega^*(Q^\lambda)$ by \@gobble{lem:omega_star_props}.(i), since $\tau>0$.
    Monotonicity and translation equivariance of $\mathcal{T}^\lambda_\Omega$ are immediate from~\eqref{eq:reg_reward}, each $\mathcal{E}^\lambda_\pi$ having them and the state-wise maximum preserving them.

\label{lem:variational_representation}
    For an admissible stationary policy $\pi$ define the discounted regularized return $J^\lambda_\pi(s):=\mathbb{E}_\pi\left[\sum_{t\geq0}\lambda^t\tilde{r}_\pi(s_t) | s_0=s\right]$, which is finite since $\tilde{r}_\pi$ is a finite vector.
    Then, for every $\lambda\in(0,1)$ and every $s\in\mathcal{S}$,
    \begin{equation}
        \label{eq:variational_representation}
        V^\lambda(s)=\max_{\pi\text{ admissible stationary}}J^\lambda_\pi(s),
    \end{equation}
    the maximum being attained at $\pi^\lambda$.

\label{lem:uniform_sup_bound}
    For every $\lambda\in(0,1)$,
    \begin{equation}
        \label{eq:uniform_sup_bound}
        (1-\lambda)\left\|V^\lambda\right\|_{\mathcal{S},\infty}\leq R_{\max},
        \qquad
        (1-\lambda)\left\|Q^\lambda\right\|_{\infty}\leq 2R_{\max}.
    \end{equation}

\label{thm:existence_fixed_point_general}
    Let \@gobble{assumption:convex-analytic-regularity,assumption:reference_policy_general,assumption:span_bounded} hold.
    Then there exist $Q^*_\Omega\in\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$ and $\rho^*_\Omega\in\mathbb{R}$ such that
    \begin{equation}
        \label{eq:fixed_point_equation}
        \mathcal{T}_\Omega\left(Q^*_\Omega\right)=Q^*_\Omega+\rho^*_\Omega\mathbf{1},
    \end{equation}
    with $\left\|Q^*_\Omega\right\|_\mathrm{sp}\leq\|r\|_\mathrm{sp}+C_V$ and $\lvert\rho^*_\Omega\rvert\leq2R_{\max}$.

\label{prop:span_bounded_necessary}
    Conversely, if~\eqref{eq:fixed_point_equation} admits a solution $(Q^*_\Omega,\rho^*_\Omega)$, then, with $V^*:=\Omega^*(Q^*_\Omega)$,
    \begin{equation*}
        \left\|V^\lambda\right\|_{\mathcal{S},\mathrm{sp}}\ \leq\ 2\left\|V^*\right\|_{\mathcal{S},\mathrm{sp}}
        \qquad\text{for every }\lambda\in(0,1),
    \end{equation*}
    so \@gobble{assumption:span_bounded} holds.
    It therefore characterizes exactly the solvability of the regularized average-reward optimality equation, as in the unregularized case \citetext{\citealp{schweitzer1978functional}; \citealp[\S8.10]{puterman1994markov}}.

Replacing $Q^*_\Omega$ by $Q^*_\Omega+c\mathbf{1}$ changes $V^*$ by $c$ (\@gobble{lem:omega_star_props}.(iii)) and leaves~\eqref{eq:fixed_point_equation} unchanged, so we may center $V^*$ so that $\|V^*\|_{\mathcal{S},\infty}=\frac{1}{2}\|V^*\|_{\mathcal{S},\mathrm{sp}}=:\kappa$.
    Taking the conjugate in~\eqref{eq:fixed_point_equation} as in~\eqref{eq:discounted_ACOE} gives the regularized average-reward optimality equation
    \begin{equation}
        \label{eq:ACOE}
        V^*+\rho^*_\Omega\mathbf{1}=\max_{\pi\text{ admissible}}\left\{\tilde{r}_\pi+P_\pi V^*\right\}.
    \end{equation}
    Set $\tilde{V}:=V^*+\frac{\rho^*_\Omega}{1-\lambda}\mathbf{1}$.
    Using~\eqref{eq:ACOE} and $P_\pi V^*\geq-\kappa\mathbf{1}$ termwise,
    \begin{equation*}
        \begin{aligned}
            \mathcal{T}^\lambda_\Omega\tilde{V}
            &=\max_\pi\left\{\tilde{r}_\pi+P_\pi V^*-(1-\lambda)P_\pi V^*\right\}+\frac{\lambda\rho^*_\Omega}{1-\lambda}\mathbf{1}\\
            &\leq V^*+\rho^*_\Omega\mathbf{1}+(1-\lambda)\kappa\mathbf{1}+\frac{\lambda\rho^*_\Omega}{1-\lambda}\mathbf{1}
            =\tilde{V}+(1-\lambda)\kappa\mathbf{1}.
        \end{aligned}
    \end{equation*}
    Hence $\mathcal{T}^\lambda_\Omega(\tilde{V}+\kappa\mathbf{1})\leq\tilde{V}+(1-\lambda)\kappa\mathbf{1}+\lambda\kappa\mathbf{1}=\tilde{V}+\kappa\mathbf{1}$ by $\lambda$-translation equivariance, and monotonicity of $\mathcal{T}^\lambda_\Omega$ (\@gobble{lem:discounted_fixed_point}) makes the iterates from $\tilde{V}+\kappa\mathbf{1}$ non-increasing, so their limit $V^\lambda$ satisfies $V^\lambda\leq\tilde{V}+\kappa\mathbf{1}$.
    The symmetric argument gives $V^\lambda\geq\tilde{V}-\kappa\mathbf{1}$, whence $\|V^\lambda-\tilde{V}\|_{\mathcal{S},\infty}\leq\kappa$ and $\|V^\lambda\|_{\mathcal{S},\mathrm{sp}}\leq\|V^*\|_{\mathcal{S},\mathrm{sp}}+2\kappa=2\|V^*\|_{\mathcal{S},\mathrm{sp}}$.

\label{assumption:weakly_communicating}
    The state space splits as $\mathcal{S}=\mathcal{C}\sqcup\mathcal{S}_{\mathrm{tr}}$, where
    \begin{enumerate}[label=(\roman*)]
        \item $\mathcal{C}$ is \emph{closed}: $s\in\mathcal{C}$, $a\in\mathcal{A}$ and $p(s'|s,a)>0$ imply $s'\in\mathcal{C}$;
        \item $\mathcal{C}$ is \emph{communicating}: for all $s,s'\in\mathcal{C}$ there exist a stationary policy $\pi$ and $k\geq0$ with $P^k_\pi(s'|s)>0$;
        \item every state of $\mathcal{S}_{\mathrm{tr}}$ is transient under every stationary policy.
    \end{enumerate}
    This is the standard definition \citep[\S8.3.1]{puterman1994markov}; $\mathcal{S}_{\mathrm{tr}}$ may be empty, in which case the MDP is communicating.

\label{lem:stopped_comparison}
    Let $\lambda\in(0,1)$, $\mathcal{B}\subseteq\mathcal{S}$, $\sigma:=\inf\{t\geq0 | s_t\in\mathcal{B}\}\in\mathbb{N}\cup\{+\infty\}$, and let $\pi$ be an admissible stationary policy.
    For every $K\geq0$ and $s\in\mathcal{S}$,
    \begin{equation}
        \label{eq:stopped_comparison}
        V^\lambda(s)\ \geq\ \mathbb{E}_\pi\left[\sum_{t=0}^{\sigma\wedge K-1}\lambda^t\tilde{r}_\pi(s_t)+\lambda^{\sigma\wedge K}V^\lambda\left(s_{\sigma\wedge K}\right) \mid s_0=s\right],
    \end{equation}
    with equality when $\pi=\pi^\lambda$.
    If moreover $\sigma<+\infty$ $\,\mathbb{P}_\pi(\cdot|s_0=s)$-almost surely, the same holds with $\sigma\wedge K$ replaced by $\sigma$.

\label{prop:weakly_communicating_implies_span}
    Let \@gobble{assumption:weakly_communicating,assumption:reference_policy_general} hold.
    Let $K^\star\geq1$ and $p^\star>0$ be such that for every ordered pair $(s,s')$ of states of $\mathcal{C}$ there is $k(s,s')\leq K^\star$ with $P^{k(s,s')}_{\tilde{\pi}}(s'|s)\geq p^\star$.
    Such constants exist, with $K^\star\leq\max\{1,\lvert\mathcal{C}\rvert-1\}\leq\lvert\mathcal{S}\rvert$, and they depend only on $p$ and $\tilde{\pi}$, not on $\lambda$. For any such pair, \@gobble{assumption:span_bounded} holds with
    \begin{equation}
        \label{eq:span_global}
        \lambda_0:=1-\frac{1}{2K^\star},
        \qquad
        C_V:=\frac{4K^\star R_{\max}}{p^\star}+4LR_{\max}.
    \end{equation}

\label{cor:mixing_implies_span}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy} hold.
    Then the MDP is communicating ($\mathcal{C}=\mathcal{S}$, $\mathcal{S}_{\mathrm{tr}}=\emptyset$, $L=0$), \@gobble{prop:weakly_communicating_implies_span} applies with $\tilde{\pi}=\mu$, $K^\star=m$ and $p^\star=\beta_m\nu_{\min}$, where $\nu_{\min}:=\min_s\nu(s)>0$, so \@gobble{assumption:span_bounded} holds with
    \begin{equation*}
        \lambda_0=1-\frac{1}{2m},
        \qquad
        C_V=\frac{4mR_{\max}}{\beta_m\nu_{\min}},
    \end{equation*}
    and \@gobble{thm:existence_fixed_point_general} gives \@gobble{thm:regularized_fixed_point}.

\label{rem:other_sufficient}
    Among the classical ergodic classes of finite MDPs \citep[\S8.3.1]{puterman1994markov}, weak communication is the weakest: both \emph{unichain} models --- in which every stationary policy induces a chain with a single recurrent class plus a possibly empty set of transient states --- and \emph{communicating} models are weakly communicating, while unichain and communicating are incomparable, neither class containing the other. \@gobble{prop:weakly_communicating_implies_span} therefore covers all these models at once.

    \@gobble{assumption:span_bounded} is nonetheless strictly weaker, being stated for the reward at hand rather than for $p$ alone: two isolated states carrying the same reward do not form a weakly communicating MDP, yet $V^\lambda$ is constant, its span vanishes and the fixed point exists. It is moreover necessary as well as sufficient (\@gobble{prop:span_bounded_necessary}), stated directly for the regularized model.

\label{prop:uniqueness_gain}
    Let \@gobble{assumption:convex-analytic-regularity} hold.
    If $\mathcal{T}_\Omega(Q_i)=Q_i+\rho_i\mathbf{1}$ for $i=1,2$, then $\rho_1=\rho_2$. No structural assumption on the MDP is needed here, unlike for the uniqueness of $Q_\Omega^*$ (\@gobble{prop:uniqueness_fixed_point}).

\label{rem:unique_terminal_weaker}
    \@gobble{assumption:weakly_communicating} implies \@gobble{assumption:unique_terminal_class}: its set $\mathcal{C}$ is terminal by closedness and connectedness, and a second terminal component $\mathcal{C}'\subseteq\mathcal{S}_{\mathrm{tr}}$ would be closed, so every stationary policy then has a recurrent state inside, contradicting~(iii).
    The converse fails: with $\mathcal{S}=\{1,2,3\}$, a self-loop and an edge $1\to2$ at state $1$, and $2\to3$, $3\to3$, the terminal component $\{3\}$ is unique, yet state $1$ is recurrent under the self-loop policy, so the MDP is not weakly communicating.

\label{rem:full_support_uniqueness}
    The full-support requirement of \@gobble{prop:uniqueness_fixed_point} is exactly~\eqref{eq:P1} (\@gobble{lem:P1_full_support}). It holds for the $\alpha$-divergences with $\alpha\leq1$ (\@gobble{thm:alpha}.(iv)), hence for both KL divergences and for the Hellinger regularizer, for the negative entropy, and for every $\epsilon$-floor-wrapped regularizer, where $\pi_{\Omega_\epsilon,Q}\geq\epsilon\mu>0$ by \@gobble{lem:floor_wrapped_props}.(ii).
    It fails for regularizers whose greedy policy may be sparse, that is for $\alpha>1$ and in particular for the $\chi^2$: there $\rho^*_\Omega$ is still unique by \@gobble{prop:uniqueness_gain}, but $Q^*_\Omega$ need not be, exactly as at $\tau=0$ \citep[\S9.1]{puterman1994markov}.

\label{def:pointwise-modulus}
    For a radius $R\geq0$, with $g_Q$ the regularization gap of \@gobble{def:mixing_objects}.(iv),
    \begin{equation*}
        \Lambda_\Omega^{\mathrm{pt}}(R):=\max_{Q\,:\,\|Q\|_\mathrm{asp}\leq R}\left\|g_Q\right\|_{\mathcal{S},\infty}.
    \end{equation*}
    The maximum is attained and finite by the argument of the proof of \@gobble{lem:modulus_properties}, and $\Lambda_\Omega(R)\leq2\Lambda_\Omega^{\mathrm{pt}}(R)$.

\label{prop:gap_optimal_q}
    Let \@gobble{assumption:m-step-mixing,assumption:convex-analytic-regularity,assumption:reference_policy} hold, and let $(Q^*,\rho^*)$ solve $\mathcal{T}(Q^*)=Q^*+\rho^*\mathbf{1}$.
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Value gap}: with $R^*:=\max\big\{\|Q^*_\Omega\|_\mathrm{asp},\max_{0\leq k<m}\|\mathcal{T}^k_\Omega(Q^*)\|_\mathrm{asp}\big\}$ and $\alpha(P)\leq1$ the Dobrushin coefficient of the transition kernel $P$ (\@gobble{def:dobrushin}),
        \begin{equation*}
            \|Q^*_\Omega-Q^*\|_\mathrm{sp}\leq\frac{m\,\alpha(P)\,\Lambda_\Omega(R^*)}{\beta_m\gamma_\Omega(R^*)^{m-1}}\leq\frac{m\,\Lambda_\Omega(R^*)}{\beta_m\gamma_\Omega(R^*)^{m-1}},
        \end{equation*}
        the right-hand sides being $+\infty$ if $\gamma_\Omega(R^*)=0$.
        \item \emph{Gain gap}: with $\underline{\Omega}:=\min_{s\in\mathcal{S}}\min_{\pi_s\in\Delta(\mathcal{A})}\Omega_s(\pi_s)$,
        \begin{equation}
            \label{eq:gain_gap}
            \min_{s\in\mathcal{S}}g_{Q^*}(s)\ \leq\ \rho^*_\Omega-\rho^*\ \leq\ \max_{s\in\mathcal{S}}g_{Q^*}(s)\ \leq\ -\tau\underline{\Omega},
        \end{equation}
        and consequently
        \begin{equation}
            \label{eq:gain_gap_modulus}
            \left\lvert\rho^*_\Omega-\rho^*\right\rvert\ \leq\ \|g_{Q^*}\|_{\mathcal{S},\infty}\ \leq\ \Lambda_\Omega^{\mathrm{pt}}(\|Q^*\|_\mathrm{asp}).
        \end{equation}
        If moreover $|\mathcal{S}|\geq2$ and $\min\Omega_s=\underline{\Omega}$ for every $s$, then $-\Lambda_\Omega(\|Q^*\|_\mathrm{asp})\leq\rho^*_\Omega-\rho^*+\tau\underline{\Omega}\leq0$.
    \end{enumerate}

The regularized fixed point $(Q^*_\Omega,\rho^*_\Omega)$ exists by \@gobble{thm:regularized_fixed_point}, and both $\mathcal{T}$ and $\mathcal{T}_\Omega$ are translation equivariant (\@gobble{cor:T_omega_props}), so that $\mathcal{T}^k(Q^*)=Q^*+k\rho^*\mathbf{1}$ and $\mathcal{T}^k_\Omega(Q^*_\Omega)=Q^*_\Omega+k\rho^*_\Omega\mathbf{1}$ for every $k\geq0$.

    \emph{(i)} The span seminorm being invariant under constants,
    \begin{equation}
        \|Q^*_\Omega-Q^*\|_\mathrm{sp} = \|\mathcal{T}^m_\Omega(Q^*_\Omega) - \mathcal{T}^m(Q^*)\|_\mathrm{sp} \leq \underbrace{\|\mathcal{T}^m_\Omega(Q^*_\Omega) - \mathcal{T}^m_\Omega(Q^*)\|_\mathrm{sp}}_{\mathrm{(a)}} + \underbrace{\|\mathcal{T}^m_\Omega(Q^*) - \mathcal{T}^m(Q^*)\|_\mathrm{sp}}_{\mathrm{(b)}}.
        \label{eq:perturbation_split_omega}
    \end{equation}
    \emph{Term (a).} Since $\|\cdot\|_\mathrm{asp}$ is invariant under constants, $\|\mathcal{T}^k_\Omega(Q^*_\Omega)\|_\mathrm{asp}=\|Q^*_\Omega\|_\mathrm{asp}$, so that for every $k\in\llbracket 1,m-1\rrbracket$,
    \begin{equation*}
        R\big[\mathcal{T}_\Omega^k(Q^*_\Omega),\mathcal{T}_\Omega^k(Q^*)\big]=\max\big\{\|Q^*_\Omega\|_\mathrm{asp},\|\mathcal{T}^k_\Omega(Q^*)\|_\mathrm{asp}\big\}\leq R^*.
    \end{equation*}
    As $\gamma_\Omega$ is non-increasing (\@gobble{def:mixing_objects}.(iii)), every factor of the product in \@gobble{lem:mixing-properties-of-regularization}.(iv), applied with $Q=Q^*_\Omega$ and $Q'=Q^*$, is at least $\gamma_\Omega(R^*)$, hence (a)~$\leq\big(1-\beta_m\gamma_\Omega(R^*)^{m-1}\big)\|Q^*_\Omega-Q^*\|_\mathrm{sp}$.

    \emph{Term (b).} Let $A_k:=\mathcal{T}^k_\Omega\big(\mathcal{T}^{m-k}(Q^*)\big)$ for $k\in\llbracket0,m\rrbracket$, so that $A_0=\mathcal{T}^m(Q^*)$ and $A_m=\mathcal{T}^m_\Omega(Q^*)$. Since $\mathcal{T}^{m-k-1}(Q^*)=Q^*+(m-k-1)\rho^*\mathbf{1}$, translation equivariance makes the constants cancel, and $k$ applications of the non-expansiveness of $\mathcal{T}_\Omega$ in $\|\cdot\|_\mathrm{sp}$ give
    \begin{equation*}
        \begin{aligned}
            \|A_{k+1}-A_k\|_\mathrm{sp}&=\big\|\mathcal{T}^k_\Omega\big(\mathcal{T}_\Omega(Q^*)\big)-\mathcal{T}^k_\Omega\big(\mathcal{T}(Q^*)\big)\big\|_\mathrm{sp}\leq\|\mathcal{T}_\Omega(Q^*)-\mathcal{T}(Q^*)\|_\mathrm{sp}\\
            &\leq\alpha(P)\Lambda_\Omega(\|Q^*\|_\mathrm{asp})\leq\alpha(P)\Lambda_\Omega(R^*),
        \end{aligned}
    \end{equation*}
    by \@gobble{lem:mixing-properties-of-regularization}.(vi), $\|Q^*\|_\mathrm{asp}\leq R^*$ and the monotonicity of $\Lambda_\Omega$ (\@gobble{lem:modulus_properties}). Summing over $k$, (b)~$\leq m\,\alpha(P)\Lambda_\Omega(R^*)$.

    Injecting both bounds into~\eqref{eq:perturbation_split_omega} yields $\beta_m\gamma_\Omega(R^*)^{m-1}\|Q^*_\Omega-Q^*\|_\mathrm{sp}\leq m\,\alpha(P)\Lambda_\Omega(R^*)$, which is the claim when $\gamma_\Omega(R^*)>0$; otherwise the bound is trivial.

    \emph{(ii)} By \@gobble{lem:mixing-properties-of-regularization}.(vi) and its proof, $\mathcal{T}_\Omega(Q)-\mathcal{T}(Q)=Pg_Q$ for every $Q$, so that $\mathcal{T}_\Omega(Q^*)=Q^*+\rho^*\mathbf{1}+Pg_{Q^*}$. Each entry of $Pg_{Q^*}$ is a convex combination of the entries of $g_{Q^*}$, and \@gobble{lem:gain_sandwich} with $c_-:=\rho^*+\min_sg_{Q^*}(s)$ and $c_+:=\rho^*+\max_sg_{Q^*}(s)$ gives the first two inequalities of~\eqref{eq:gain_gap}. The last one is the upper part of \@gobble{lem:omega_star_props}.(ii), which needs no assumption on the Diracs: $g_{Q^*}(s)\leq-\tau\underline{\Omega}_s\leq-\tau\underline{\Omega}$. Finally,~\eqref{eq:gain_gap_modulus} follows from~\eqref{eq:gain_gap} and \@gobble{def:pointwise-modulus}.
    For the last claim, fix $s$ and $s_0\neq s$, and let $\tilde{Q}$ equal $Q^*$ except at $s_0$, where it is constant in the action. Then $\|\tilde{Q}\|_\mathrm{asp}\leq\|Q^*\|_\mathrm{asp}$, and since $g_Q(s)$ only depends on $Q(s,\cdot)$ and equals $-\tau\min\Omega_{s_0}$ at a constant, $g_{\tilde{Q}}(s)=g_{Q^*}(s)$ and $g_{\tilde{Q}}(s_0)=-\tau\underline{\Omega}$; hence $-\tau\underline{\Omega}-g_{Q^*}(s)\leq\|g_{\tilde{Q}}\|_{\mathcal{S},\mathrm{sp}}\leq\Lambda_\Omega(\|Q^*\|_\mathrm{asp})$. Together with $g_{Q^*}\leq-\tau\underline{\Omega}$ and~\eqref{eq:gain_gap}, this gives the claim.

\label{def:floor_wrapped}
    Let $\Omega_0$ be a base regularization satisfying \@gobble{assumption:convex-analytic-regularity} and let $\epsilon\in[0,1)$. The $\epsilon$-floor-wrapped regularization $\Omega_\epsilon$ is defined state-wise by
    \begin{equation*}
        \Omega_{\epsilon,s}(\pi_s) = \begin{cases}
            (1-\epsilon)\,\Omega_{0,s}\left(\frac{\pi_s-\epsilon\mu_s}{1-\epsilon}\right) & \text{if } \pi_s\in\Delta_\epsilon(s),\\[2ex]
            +\infty & \text{otherwise.}
        \end{cases}
    \end{equation*}
    Equivalently, $\Omega_{\epsilon,s} = (1-\epsilon)\left(\Omega_{0,s}\circ\Phi_{\epsilon,s}^{-1}\right) + \iota_{\Delta_\epsilon(s)}$, where $\iota_C$ denotes the convex indicator of the set $C$, equal to $0$ on $C$ and $+\infty$ elsewhere. For $\epsilon=0$ we recover $\Omega_0$.

\phantomsection\hypertarget{proof:floor_wrapped_props}{}
    Fix $s\in\mathcal{S}$ and write $\mu_s=\mu(\cdot|s)$, $\Phi=\Phi_{\epsilon,s}$ for the affine bijection of \@gobble{def:floored_simplex}.

    \emph{Effective domain and properness}. Since $\Omega_{\epsilon,s}(\Phi(p))=(1-\epsilon)\Omega_{0,s}(p)$ for $p\in\Delta(\mathcal{A})$ and $\Omega_{\epsilon,s}=+\infty$ outside $\Delta_\epsilon(s)=\Phi(\Delta(\mathcal{A}))$, the effective domain of $\Omega_{\epsilon,s}$ is $\Phi(\mathrm{dom}(\Omega_{0,s}))$. It is non-empty since $\Omega_{0,s}$ is proper, and $\Omega_{\epsilon,s}$ never takes the value $-\infty$ since $\Omega_{0,s}$ does not; hence $\Omega_{\epsilon,s}$ is proper. Moreover $\Phi(\mu_s)=\mu_s$, so $\Omega_{\epsilon,s}(\mu_s)=(1-\epsilon)\Omega_{0,s}(\mu_s)$, which gives \@gobble{assumption:reference_policy} for $\Omega_\epsilon$ whenever it holds for $\Omega_0$.

    \emph{Closedness}. $\Delta_\epsilon(s)$ is the intersection of the simplex with the closed half-spaces $\{\pi_s : \pi_s(a)\geq\epsilon\mu(a|s)\}$, hence closed and convex. The map $\Omega_{0,s}\circ\Phi^{-1}$ is proper, convex and lower semicontinuous as the composition of a proper, closed convex function with a continuous affine map, hence closed, a proper convex function being closed if and only if it is lower semicontinuous \citep[Theorem~7.1]{rockafellar1970convex}; and $\iota_{\Delta_\epsilon(s)}$ is closed since $\Delta_\epsilon(s)$ is closed. A sum of closed functions is closed.

    \emph{Strong convexity}. Let $\pi_s,\pi'_s\in\mathrm{dom}(\Omega_{\epsilon,s})$, $t\in[0,1]$, and set $p=\Phi^{-1}(\pi_s)$, $p'=\Phi^{-1}(\pi'_s)$, so that $\pi_s-\pi'_s=(1-\epsilon)(p-p')$. Since $\Phi^{-1}$ is affine, $\Phi^{-1}(t\pi_s+(1-t)\pi'_s)=tp+(1-t)p'$, and the $\sigma$-strong convexity of $\Omega_{0,s}$ gives
    \begin{align*}
        \Omega_{\epsilon,s}(t\pi_s+(1-t)\pi'_s) &= (1-\epsilon)\Omega_{0,s}\!\left(tp+(1-t)p'\right)\\
        &\leq (1-\epsilon)\left[t\,\Omega_{0,s}(p)+(1-t)\,\Omega_{0,s}(p')-\frac{\sigma}{2}t(1-t)\|p-p'\|^2\right]\\
        &= t\,\Omega_{\epsilon,s}(\pi_s)+(1-t)\,\Omega_{\epsilon,s}(\pi'_s)-\frac{\sigma}{2(1-\epsilon)}t(1-t)\|\pi_s-\pi'_s\|^2,
    \end{align*}
    using $\|p-p'\|^2=\|\pi_s-\pi'_s\|^2/(1-\epsilon)^2$ in the last line. Hence $\Omega_{\epsilon,s}$ is $\frac{\sigma}{1-\epsilon}$-strongly convex, and together with $\tau>0$ this shows that $\Omega_\epsilon$ satisfies \@gobble{assumption:convex-analytic-regularity}.

    \emph{(i)}. The constraint $\pi_s\in\Delta_\epsilon(s)$ is exactly the range of $\Phi$, so the change of variable $\pi_s=\Phi(p)=\epsilon\mu_s+(1-\epsilon)p$ is a bijection from $\Delta(\mathcal{A})$ onto $\Delta_\epsilon(s)$. Since $\Omega_{\epsilon,s}(\Phi(p))=(1-\epsilon)\Omega_{0,s}(p)$ and $\langle\Phi(p),Q_s\rangle=\epsilon\langle\mu_s,Q_s\rangle+(1-\epsilon)\langle p,Q_s\rangle$, we get
    \begin{align*}
        \Omega_\epsilon^*(Q)(s) &= \max_{\pi_s\in\Delta(\mathcal{A})}\left\{\langle\pi_s,Q_s\rangle-\tau\Omega_{\epsilon,s}(\pi_s)\right\}\\
        &= \max_{\pi_s\in\Delta_\epsilon(s)}\left\{\langle\pi_s,Q_s\rangle-\tau\Omega_{\epsilon,s}(\pi_s)\right\}\\
        &= \max_{p\in\Delta(\mathcal{A})}\left\{\epsilon\langle\mu_s,Q_s\rangle+(1-\epsilon)\langle p,Q_s\rangle-\tau(1-\epsilon)\,\Omega_{0,s}(p)\right\}\\
        &= \epsilon\langle\mu_s,Q_s\rangle+(1-\epsilon)\max_{p\in\Delta(\mathcal{A})}\left\{\langle p,Q_s\rangle-\tau\Omega_{0,s}(p)\right\}\\
        &= \epsilon\langle\mu_s,Q_s\rangle+(1-\epsilon)\Omega_0^*(Q)(s),
    \end{align*}
    where the second equality holds because $\Omega_{\epsilon,s}=+\infty$ outside $\Delta_\epsilon(s)$, the third is the change of variable, the fourth uses $1-\epsilon>0$, and the last is the definition of $\Omega_0^*$. The map $Q_s\mapsto\epsilon\langle\mu_s,Q_s\rangle$ is linear with constant gradient $\epsilon\mu_s$, so $\Omega_\epsilon^*$ is differentiable as soon as $\Omega_0^*$ is (which is the case by \@gobble{lem:omega_star_props}.(i) since $\tau >0$), with $\nabla\Omega_\epsilon^*=\epsilon\mu_s+(1-\epsilon)\nabla\Omega_0^*$; if $\nabla\Omega_0^*$ is $L_0$-Lipschitz then $\nabla\Omega_\epsilon^*$ is $(1-\epsilon)L_0$-Lipschitz.

    \emph{(ii)}. The maximum over $p$ in the third line above is attained at $p^\star=\operatorname*{arg\,max}_{p\in\Delta(\mathcal{A})}\{\langle p,Q_s\rangle-\tau\Omega_{0,s}(p)\}=\pi_{\Omega_0,Q}(\cdot|s)$, which is unique by \@gobble{lem:omega_star_props}.(i) applied to $\Omega_0$. Since $\Phi$ is a bijection, the maximizer of the original problem is $\pi_{\Omega_\epsilon,Q}(\cdot|s)=\Phi(p^\star)=\epsilon\mu_s+(1-\epsilon)\pi_{\Omega_0,Q}(\cdot|s)$. This is consistent with (i) and \@gobble{lem:omega_star_props}.(i), which identify the greedy policy with $\nabla\Omega_\epsilon^*(Q)(s)$.

    \emph{(iii)}. Let $(s,a)\in\mathcal{S}\times\mathcal{A}$ and $Q$ with $\|Q\|_\mathrm{asp}\leq R$. Dividing (ii) by $\mu(a|s)>0$ gives
    \begin{equation*}
        \frac{\pi_{\Omega_\epsilon,Q}(a|s)}{\mu(a|s)} = \epsilon+(1-\epsilon)\frac{\pi_{\Omega_0,Q}(a|s)}{\mu(a|s)}.
    \end{equation*}
    Taking the infimum over $(s,a)$ and over $\{Q : \|Q\|_\mathrm{asp}\leq R\}$, we obtain $\gamma_{\Omega_\epsilon}(R)=\epsilon+(1-\epsilon)\gamma_{\Omega_0}(R)$ from \@gobble{def:mixing_objects}.(iii). Since $\gamma_{\Omega_0}(R)\geq0$ and $\epsilon<1$, we get $\gamma_{\Omega_\epsilon}(R)\geq\epsilon$ for every $R\geq0$.

    \emph{(iv)}. Trivial from (i).

    \emph{(v)}. Let $Q$ satisfy $\|Q\|_\mathrm{asp}\leq R$ and write $g^\epsilon_Q$ and $g^0_Q$ for the regularization gaps of $\Omega_\epsilon$ and $\Omega_0$. Subtracting $\max_a Q_s(a)$ from (i) gives, for every $s\in\mathcal{S}$,
    \begin{equation*}
        g^\epsilon_Q(s) = \epsilon\,h_Q(s) + (1-\epsilon)\,g^0_Q(s), \qquad h_Q(s) := \langle\mu_s,Q_s\rangle-\max_a Q_s(a).
    \end{equation*}
    Since $\mu_s\in\Delta(\mathcal{A})$, we have $h_Q(s)\in\left[-\|Q_s\|_{\mathcal{A},\mathrm{sp}},0\right]\subseteq[-R,0]$ for every $s$, hence $\|h_Q\|_{\mathcal{S},\mathrm{sp}}\leq R$. The triangle inequality and \@gobble{def:mixing_objects}.(iv) applied to $\Omega_0$ give
    \begin{equation*}
        \|g^\epsilon_Q\|_{\mathcal{S},\mathrm{sp}} \leq \epsilon\|h_Q\|_{\mathcal{S},\mathrm{sp}} + (1-\epsilon)\|g^0_Q\|_{\mathcal{S},\mathrm{sp}} \leq \epsilon R + (1-\epsilon)\Lambda_{\Omega_0}(R).
    \end{equation*}
    Taking the maximum over $\{Q : \|Q\|_\mathrm{asp}\leq R\}$ yields $\Lambda_{\Omega_\epsilon}(R)\leq\epsilon R+(1-\epsilon)\Lambda_{\Omega_0}(R)$. The last claim follows from \@gobble{rem:bounded_modulus} applied to $\Omega_0$.

\label{lem:floor_global}
    Let \@gobble{assumption:m-step-mixing} hold, let $\Omega_0$ satisfy \@gobble{assumption:convex-analytic-regularity}, let $\epsilon\in(0,1)$, and let $Q,Q'$ be two $Q$-value functions. Then:
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Global $m$-step contraction}:
        \begin{equation*}
            \begin{aligned}
                \|\mathcal{T}^m_{\Omega_\epsilon}(Q)-\mathcal{T}^m_{\Omega_\epsilon}(Q')\|_\mathrm{sp}
                &\leq\Big(1-\beta_m\prod_{k=1}^{m-1}\gamma_{\Omega_\epsilon}\big(R[\mathcal{T}_{\Omega_\epsilon}^k(Q),\mathcal{T}_{\Omega_\epsilon}^k(Q')]\big)\Big)\|Q-Q'\|_\mathrm{sp}\\
                &\leq\left(1-\beta_m\epsilon^{m-1}\right)\|Q-Q'\|_\mathrm{sp}.
            \end{aligned}
        \end{equation*}
        \item \emph{Global coverage}: let $(Q_n)_{n\geq0}$ be $Q$-functions and let $(s_n,a_n)_{n\geq0}$ be a trajectory with $a_n\sim\pi_{\Omega_\epsilon,Q_n}(\cdot|s_n)$ and $s_{n+1}\sim p(\cdot|s_n,a_n)$; let $\mathcal{F}_n:=\sigma(Q_0,(s_0,a_0),\dots,(s_n,a_n))$ and assume that $Q_n$ is $\mathcal{F}_{n-1}$-measurable for $n\geq1$. Then for all $t\geq0$ and all $(s,a)$:
        \begin{equation}
            \mathbb{P}\left((s_{t+m},a_{t+m})=(s,a)\mid\mathcal{F}_t\right) \geq \beta_m\epsilon^m\eta(s,a) \geq \beta_m\epsilon^m\eta_{\min}.
        \end{equation}
        \item \emph{Fixed point up to a constant}: there exists $Q^*_{\Omega_\epsilon}\in\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$, unique up to an additive constant, and a unique $\rho^*_{\Omega_\epsilon}\in\mathbb{R}$, such that $\mathcal{T}_{\Omega_\epsilon}(Q^*_{\Omega_\epsilon}) = Q^*_{\Omega_\epsilon} + \rho^*_{\Omega_\epsilon}\mathbf{1}$.
    \end{enumerate}

\label{rem:floor_bias}
    Applying \@gobble{prop:gap_optimal_q} to $\Omega_\epsilon$, which satisfies its assumptions by \@gobble{lem:floor_wrapped_props}, and using \@gobble{lem:floor_wrapped_props}.(iii) and (v) gives
    \begin{equation*}
        \|Q^*_{\Omega_\epsilon}-Q^*\|_\mathrm{sp} \leq \frac{m\left(\epsilon R^* + (1-\epsilon)\Lambda_{\Omega_0}(R^*)\right)}{\beta_m(\epsilon+(1-\epsilon)\gamma_{\Omega_0}(R^*))^{m-1}},
    \end{equation*}
    where $R^*$ is the radius of \@gobble{prop:gap_optimal_q} associated with $\Omega_\epsilon$. The floor therefore trades a \emph{global} contraction rate $\beta_m\epsilon^{m-1}$ against a bias term of order $\epsilon R^*$ which does not vanish as $\tau\to 0$: small $\epsilon$ keeps the fixed point close to $Q^*$ but degrades the rate, large $\epsilon$ does the opposite.

\label{def:sub_blocks}
    Let $\kappa_0 > 0$ be a fixed sub-block budget. We define recursively the sub-blocks $J_n = \{t_n, \ldots, t_{n+1}-1\}$ by $t_0 = 0$ and
    \begin{equation}
        \label{eq:subblocks}
        t_{n+1} = \min\left\{t > t_n \Big| \sum_{k=t_n}^{t-1} \alpha_k \geq \kappa_0\right\},
    \end{equation}
    and the $i$-th global block as the chronological concatenation of $m$ consecutive sub-blocks,
    \begin{equation}
        \label{eq:block}
        \mathcal{B}_i = \bigcup_{\ell=0}^{m-1} J_{im+\ell}, \qquad b_i := \min \mathcal{B}_i = t_{im}.
    \end{equation}
    Note that these definitions are valid under \@gobble{assumption:lr}.

    We write $\Phi^{(i)} := F_{b_{i+1}-1}\circ\ldots\circ F_{b_i}$, so that $Q_{b_{i+1}} = \Phi^{(i)}(Q_{b_i})$ and, by \@gobble{lem:reference_trajectory_synchronous}, $Q^*_{b_{i+1}} = \Phi^{(i)}(Q^*_{b_i})$.

\label{lem:product_doeblin_synchronous}
    Let $R>0$, let $(U_k)_{k\in\mathcal{K}}$ be a finite family of $Q$-functions with $\|U_k\|_\mathrm{asp}\leq R$ for every $k$, and let $K_k:=K_{\pi_{\Omega,U_k}}$, i.e.\ $K_k(s',a'|s,a)=p(s'|s,a)\,\pi_{\Omega,U_k}(a'|s')$. For a subset $\mathcal{C}=\{k_1<\ldots<k_n\}\subseteq\mathcal{K}$, let $K_{\mathcal{C}}:=K_{k_n}\cdots K_{k_1}$ be the associated ordered product. Then $K_{\mathcal{C}}$ is row-stochastic and:
    \begin{enumerate}[label=(\roman*)]
        \item if $n\geq m$, then $\|K_{\mathcal{C}}\|_{\mathrm{sp},\mathrm{op}}\leq1-\tilde{\beta}_m(R)$, where $\tilde{\beta}_m(R):=\beta_m\,\gamma_\Omega(R)^{m-1}$;
        \item if $n<m$, then $\|K_{\mathcal{C}}\|_{\mathrm{sp},\mathrm{op}}\leq1$.
    \end{enumerate}

\label{lem:pickup_synchronous}
    Let $\mathcal{B}_i$ be the $i$-th global block of \@gobble{def:sub_blocks}, let $(X_k)_{k \in \mathcal{B}_i}$ be auxiliary independent Bernoulli random variables with $X_k \sim \mathcal{B}(\alpha_k)$ and let $N_i := \sum_{k\in \mathcal{B}_i} X_k$. Under \@gobble{assumption:lr},
    \begin{equation}
        \label{eq:pickup_synchronous}
        \mathbb{P}(N_i \geq m) \geq p_m := \left(1-e^{-\kappa_0}\right)^m.
    \end{equation}

For each of the $m$ sub-blocks $J_n \subseteq \mathcal{B}_i$, let $\mathcal{U}_n := \bigcup_{k\in J_n}\{X_k = 1\}$ be the event that at least one effective update occurs in $J_n$. By independence of the $X_k$ and $1-u \leq e^{-u}$,
    \begin{equation*}
        \mathbb{P}(\mathcal{U}_n) = 1 - \prod_{k\in J_n}(1-\alpha_k) \geq 1 - \exp\left(-\sum_{k\in J_n}\alpha_k\right) \geq 1 - e^{-\kappa_0},
    \end{equation*}
    the last inequality by the definition~\eqref{eq:subblocks} of the sub-block. The sub-blocks of $\mathcal{B}_i$ have disjoint index sets, so the events $\mathcal{U}_{im}, \ldots, \mathcal{U}_{im+m-1}$ are independent, and $\bigcap_{\ell=0}^{m-1} \mathcal{U}_{im+\ell} \subseteq \{N_i \geq m\}$. Hence $\mathbb{P}(N_i \geq m) \geq \prod_{\ell=0}^{m-1}\mathbb{P}(\mathcal{U}_{im+\ell}) \geq (1-e^{-\kappa_0})^m$.

\label{lem:jacobian_bound_synchronous}
    Under \@gobble{assumption:lr}, for every global block $\mathcal{B}_i$ and every $\tilde{Q}\in[Q_{b_i},Q^*_{b_i}]$,
    \begin{equation*}
        \|D\Phi^{(i)}(\tilde{Q})\|_{\mathrm{sp},\mathrm{op}} \leq 1 - p_m\,\tilde{\beta}_m(\bar{R}_i).
    \end{equation*}

By the chain rule and \@gobble{cor:T_omega_props}, the Jacobian of $\Phi^{(i)}$ at $\tilde{Q}$ is
    \begin{equation*}
        D\Phi^{(i)}(\tilde{Q}) = \prod_{k\in \mathcal{B}_i} \left((1-\alpha_{k})I + \alpha_{k} K_{k}\right), \qquad K_k:=K_{\pi_{\Omega,\tilde{Q}_k}},\quad \tilde{Q}_k := F_{k-1}\circ\ldots\circ F_{b_i}(\tilde{Q}),
    \end{equation*}
    the product being written in decreasing order of $k$. By \@gobble{lem:frozen_flow_bounded_synchronous}, $\|\tilde{Q}_k\|_\mathrm{asp} \leq \bar{R}_i$ for every $k\in \mathcal{B}_i$, so the family $(K_k)_{k\in \mathcal{B}_i}$ satisfies the hypotheses of \@gobble{lem:product_doeblin_synchronous} with $U_k=\tilde{Q}_k$ and $R=\bar{R}_i$.

    We introduce a probabilistic argument to bound the Jacobian. Let $(X_k)_{k\in \mathcal{B}_i}$ be the auxiliary Bernoulli variables of \@gobble{lem:pickup_synchronous}, realized as the coordinate maps of the finite product space $\{0,1\}^{\mathcal{B}_i}$ endowed with $\bigotimes_{k\in\mathcal{B}_i}\mathcal{B}(\alpha_k)$, which is well defined since $\alpha_k\in(0,1]$ by \@gobble{assumption:lr}. The flow~\eqref{eq:sync_fk_update} being deterministic, this finite space carries all the randomness of the argument. We define $Y_k = (1-X_k)I + X_k K_{k}$, so that $(1-\alpha_{k})I + \alpha_{k} K_{k} = \mathbb{E}[Y_k]$. By independence of the $Y_k$, we have $\prod_{k\in \mathcal{B}_i} \mathbb{E}[Y_k] = \mathbb{E}\left[\prod_{k\in \mathcal{B}_i} Y_k\right]$, and the triangle inequality gives
    \begin{equation*}
        \|D\Phi^{(i)}(\tilde{Q})\|_{\mathrm{sp},\mathrm{op}} = \left\|\mathbb{E}\left[\prod_{k\in \mathcal{B}_i} Y_k\right]\right\|_{\mathrm{sp},\mathrm{op}} \leq \mathbb{E}\left[\left\|\prod_{k\in \mathcal{B}_i} Y_k\right\|_{\mathrm{sp},\mathrm{op}}\right].
    \end{equation*}
    Let $\mathcal{C} := \{k \in \mathcal{B}_i \mid X_k = 1\}$, so that $N_i = |\mathcal{C}|$. Since the factors equal to $I$ can be removed from the product, we have the pathwise identity $\prod_{k\in \mathcal{B}_i} Y_k = K_{\mathcal{C}}$ with the notation of \@gobble{lem:product_doeblin_synchronous}.

    On the event $\{N_i \geq m\}$, point (i) of \@gobble{lem:product_doeblin_synchronous} gives $\|K_{\mathcal{C}}\|_{\mathrm{sp},\mathrm{op}} \leq 1 - \tilde{\beta}_m(\bar{R}_i)$, and on the event $\{N_i < m\}$, point (ii) gives $\|K_{\mathcal{C}}\|_{\mathrm{sp},\mathrm{op}} \leq 1$; hence $\|K_{\mathcal{C}}\|_{\mathrm{sp},\mathrm{op}} \leq 1-\tilde{\beta}_m(\bar{R}_i)\mathbb{1}_{\{N_i\geq m\}}$ pointwise. Taking expectations,
    \begin{equation*}
        \|D\Phi^{(i)}(\tilde{Q})\|_{\mathrm{sp},\mathrm{op}} \leq 1 - \mathbb{P}(N_i \geq m)\,\tilde{\beta}_m(\bar{R}_i) \leq 1 - p_m\tilde{\beta}_m(\bar{R}_i),
    \end{equation*}
    the last inequality by \@gobble{lem:pickup_synchronous}.

\label{lem:block_contraction_synchronous}
    Under \@gobble{assumption:lr}, for every global block $\mathcal{B}_i$,
    \begin{equation*}
        e_{b_{i+1}} \leq \left(1 - p_m\,\tilde{\beta}_m(\bar{R}_i)\right) e_{b_i}.
    \end{equation*}

\label{cor:full_knowledge_m_1}
    Assume $m=1$ and $\alpha_t\in(0,1]$ for every $t$. For any initialization $Q_0$, the iterates of~\eqref{eq:sync_fk_update} satisfy
    \begin{equation*}
        e_T \leq \prod_{k=0}^{T-1} (1-\alpha_k\beta_1)\,e_0.
    \end{equation*}
    In particular, $Q$-iteration ($\alpha_t\equiv1$) contracts at rate $1-\beta_1$ per sweep, and reaches $e_T\leq\varepsilon$ after $O\big(|\mathcal{S}|^2|\mathcal{A}|\,\beta_1^{-1}\log(e_0/\varepsilon)\big)$ model queries.

Let $\Psi_T := F_{T-1}\circ\ldots\circ F_0$ and $\tilde{Q}\in[Q_0,Q^*_0]$. As in \@gobble{lem:jacobian_bound_synchronous}, $D\Psi_T(\tilde{Q}) = \prod_{k=0}^{T-1}\left((1-\alpha_k)I + \alpha_k P_k\right)$. By \@gobble{lem:terminal_action} with $n=1$, each factor satisfies
    \begin{equation*}
        \left((1-\alpha_k)I + \alpha_k K_k\right)(s',a'|s,a) \geq \alpha_k K_k(s',a'|s,a) \geq \alpha_k\beta_1\,\nu(s')\,\pi_{\Omega,\tilde{Q}_k}(a'|s'),
    \end{equation*}
    which is a Doeblin condition with parameter $\alpha_k\beta_1$. \@gobble{lem:dobrushin_doeblin,lem:row-stochastic-span} give $\left\|(1-\alpha_k)I + \alpha_k P_k\right\|_{\mathrm{sp},\mathrm{op}} \leq 1-\alpha_k\beta_1$, and the submultiplicativity of the operator span seminorm together with \@gobble{prop:mvi-span} and \@gobble{lem:reference_trajectory_synchronous} conclude. For $\alpha_t\equiv1$, the update~\eqref{eq:sync_fk_update} is $Q$-iteration without the centering projection, which is invisible to $\|\cdot\|_\mathrm{sp}$, so $e_T\leq(1-\beta_1)^Te_0\leq\varepsilon$ for $T\geq\beta_1^{-1}\log(e_0/\varepsilon)$, each sweep using $|\mathcal{S}|^2|\mathcal{A}|$ queries.

By definition of $I(T)$ we have $b_{I(T)} \leq T < b_{I(T)+1}$, and by \@gobble{lem:sum_block} each global block consumes at most $m(\kappa_0+\alpha_0)$. The step sizes being non-negative,
    \begin{equation*}
        \sum_{k=0}^{T-1}\alpha_k \leq \sum_{k=0}^{b_{I(T)+1}-1}\alpha_k < (I(T)+1)\,m(\kappa_0+\alpha_0), \qquad \text{i.e.} \qquad I(T) > \frac{\sum_{k=0}^{T-1}\alpha_k}{m(\kappa_0+\alpha_0)} - 1,
    \end{equation*}
    and $I(T)$ being an integer gives the claim.

\label{rem:chernoff_alternative}
    Each global block has a total budget $\bar\alpha_i := \sum_{k\in \mathcal{B}_i}\alpha_k \geq m\kappa_0$, so for $\kappa_0 > 1$ the multiplicative Chernoff inequality for the lower tail \citep[Theorem~4.5]{mitzenmacher2005probability} gives
    \begin{equation*}
        \mathbb{P}(N_i < m) \leq \exp\left(-\frac{(\bar\alpha_i-m)^2}{2\bar\alpha_i}\right) \leq \exp\left(-\frac{(\kappa_0-1)^2}{2\kappa_0}m\right),
    \end{equation*}
    the last inequality because $u \mapsto \frac{(u-m)^2}{2u}$ has derivative $\frac{1}{2}\left(1-\frac{m^2}{u^2}\right) > 0$ on $(m,\infty)$ and is therefore minimized at $u = m\kappa_0$. This variant requires $\kappa_0 > 1$ but is much better for large $m$, since it tends to $1$ whereas $(1-e^{-\kappa_0})^m$ decays exponentially in $m$. Both bounds being valid, \@gobble{lem:pickup_synchronous} holds with
    \begin{equation*}
        p_m = \max\left\{\left(1-e^{-\kappa_0}\right)^m,\ 1-\exp\left(-\frac{(\kappa_0-1)^2}{2\kappa_0}m\right)\mathbb{1}\{\kappa_0>1\}\right\}.
    \end{equation*}
    The proof of \@gobble{thm:sync-stoch-main} uses $\kappa_0 = 4$, for which $p_m \geq 1-e^{-9/8} \geq \frac12$.

\label{def:localized-radii}
    For a radius $R\geq e_0$, define the exit time
    \begin{equation}
        \label{eq:exit-time}
        \sigma_R := \inf\left\{t\in\mathbb{N}\ \middle|\ e_t>R\right\} \in \mathbb{N}\cup\{+\infty\},
    \end{equation}
    the \emph{domination radius} and the \emph{noise radius}
    \begin{equation*}
        A_R := \|Q^*_\Omega\|_\mathrm{asp} + R, \qquad C_R := \|Q^*_\Omega\|_\mathrm{sp} + R,
    \end{equation*}
    and the localized constants
    \begin{equation}
        \label{eq:localized-constants}
        \tilde{\beta}_m(A_R) := \beta_m\,\gamma_\Omega(A_R)^{m-1}, \quad \bar{\beta}(R) := p_m\,\tilde{\beta}_m(A_R) \in (0,1), \quad \bar{w}(R) := C_R + \left\|\Omega^*(0)\right\|_{\mathcal{S},\mathrm{sp}},
    \end{equation}
    where $p_m$ is the constant of \@gobble{lem:pickup_synchronous} (see also \@gobble{rem:chernoff_alternative}).

\label{lem:virtual-flow-R}
    Let $i\in\mathbb{N}$ with $e_{b_i}\leq R$. Then, pathwise:
    \begin{enumerate}[label=(\roman*)]
        \item $\|\tilde{Q}_k-Q^*_\Omega\|_\mathrm{sp} \leq e_{b_i}$ for every $k\geq b_i$;
        \item $\|\tilde{Q}_{b_{i+1}}-Q^*_\Omega\|_\mathrm{sp} \leq \left(1-\bar{\beta}(R)\right)e_{b_i}$.
    \end{enumerate}

\label{lem:good-event}
    Let $\delta\in(0,1)$ and $\delta' := \frac{\delta}{I_{\max}+1}$. The event
    \begin{equation}
        \label{eq:good-event}
        G_R(\delta) := \bigcap_{i=0}^{I(T)-1}\left\{\max_{b_i\leq k\leq b_{i+1}}\left\|\widehat{U}^{(\mathcal{B}_i)}_k\right\|_\infty\leq\bar{U}_{\mathcal{B}_i}(\delta')\right\} \cap \left\{\max_{b_{I(T)}\leq k\leq T}\left\|\widehat{U}^{(\mathcal{B}_{\mathrm{res}})}_k\right\|_\infty\leq\bar{U}_{\mathcal{B}_{\mathrm{res}}}(\delta')\right\}
    \end{equation}
    satisfies $\mathbb{P}\left(G_R(\delta)\right)\geq1-\delta$.

If $\sigma_R\leq t_a$ the range reduces to $k=t_a$, where $E_{t_a}=0$. Otherwise, for $t_a\leq k<\min\{t_b+1,\sigma_R\}$ the true update~\eqref{eq:sync-stoch-update} occurs and $W_{k+1}=\widehat{W}_{k+1}$ by \@gobble{lem:stopped-noise}. Subtracting~\eqref{eq:virtual-sequence} from~\eqref{eq:sync-stoch-update} and using the average-path identity of \@gobble{lem:mixing-properties-of-regularization}.(i) at the pair $(Q_k,\tilde{Q}_k)$, i.e.\ $\mathcal{T}_\Omega(Q_k)-\mathcal{T}_\Omega(\tilde{Q}_k)=\bar{K}_kE_k$ with $\bar{K}_k := K_{\bar{\pi}_{\Omega,[Q_k,\tilde{Q}_k]}}$,
    \begin{equation}
        \label{eq:sync-err-rec-R}
        E_{k+1} = (1-\alpha_k)E_k+\alpha_k\bar{K}_kE_k+\alpha_k\widehat{W}_{k+1} = M_kE_k+\alpha_k\widehat{W}_{k+1},
    \end{equation}
    where $M_k := (1-\alpha_k)I+\alpha_k\bar{K}_k$ is row-stochastic as a convex combination of row-stochastic matrices.

    Decompose $E_k = \widehat{R}_k+\widehat{U}^{(\mathcal{K})}_k$ with $\widehat{R}_{t_a}=0$. The noise terms in~\eqref{eq:sync-err-rec-R} cancel with the definition of $\widehat{U}^{(\mathcal{K})}_{k+1}$, so that $\widehat{R}_{k+1} = M_k\widehat{R}_k+\alpha_k\left(\bar{K}_k-I\right)\widehat{U}^{(\mathcal{K})}_k$. Since $\bar{K}_k$ is row-stochastic, every entry of $\bar{K}_k\widehat{U}^{(\mathcal{K})}_k$ is a convex combination of entries of $\widehat{U}^{(\mathcal{K})}_k$, hence lies in $\left[\min\widehat{U}^{(\mathcal{K})}_k,\max\widehat{U}^{(\mathcal{K})}_k\right]$, and so does every entry of $\widehat{U}^{(\mathcal{K})}_k$; therefore every entry of $\left(\bar{K}_k-I\right)\widehat{U}^{(\mathcal{K})}_k$ lies in $\left[-\|\widehat{U}^{(\mathcal{K})}_k\|_\mathrm{sp},\|\widehat{U}^{(\mathcal{K})}_k\|_\mathrm{sp}\right]$ and $\left\|\alpha_k\left(\bar{K}_k-I\right)\widehat{U}^{(\mathcal{K})}_k\right\|_\mathrm{sp} \leq 2\alpha_k\left\|\widehat{U}^{(\mathcal{K})}_k\right\|_\mathrm{sp} \leq 4\alpha_k\left\|\widehat{U}^{(\mathcal{K})}_k\right\|_\infty$. By \@gobble{lem:row-stochastic-span} the row-stochastic matrix $M_k$ is span non-expansive, so $\|\widehat{R}_{k+1}\|_\mathrm{sp}\leq\|\widehat{R}_k\|_\mathrm{sp}+4\alpha_k\|\widehat{U}^{(\mathcal{K})}_k\|_\infty$. Summing from $t_a$ and using the definition of $G_R(\delta)$, for every $k\in\llbracket t_a,\min\{t_b+1,\sigma_R\}\rrbracket$, $\|\widehat{R}_k\|_\mathrm{sp} \leq 4\left(\sum_{k'\in\mathcal{K}}\alpha_{k'}\right)\bar{U}_\mathcal{K}(\delta')$ and
    \begin{equation*}
        \|E_k\|_\mathrm{sp} \leq \|\widehat{R}_k\|_\mathrm{sp}+2\left\|\widehat{U}^{(\mathcal{K})}_k\right\|_\infty \leq 2\left(1+2\sum_{k'\in\mathcal{K}}\alpha_{k'}\right)\bar{U}_\mathcal{K}(\delta') = \varepsilon_\mathcal{K}(\delta').
    \end{equation*}

\label{prop:no-escape}
    Let $\delta\in(0,1)$, $R\geq e_0$, $\delta'=\frac{\delta}{I_{\max}+1}$ and
    \begin{equation*}
        \bar{\varepsilon}_R(\delta) := \max\left\{\max_{0\leq i<I(T)}\varepsilon_{\mathcal{B}_i}(\delta'),\ \varepsilon_{\mathcal{B}_{\mathrm{res}}}(\delta')\right\}.
    \end{equation*}
    Assume the \emph{radius admissibility condition}
    \begin{equation}
        \label{eq:R-admissible}
        \bar{\varepsilon}_R(\delta) \leq \frac{\bar{\beta}(R)}{\bar{\beta}(R)+1}\left(R-e_0\right).
    \end{equation}
    Then, on the event $G_R(\delta)$, we have $\sigma_R>T$, in particular $\sup_{0\leq t\leq T}e_t\leq R$, and for every $0\leq i\leq I(T)$,
    \begin{equation}
        \label{eq:block-recursion-R}
        e_{b_i} \leq (1-\bar{\beta}(R))^ie_0+\sum_{\ell=0}^{i-1}(1-\bar{\beta}(R))^{i-1-\ell}\varepsilon_{\mathcal{B}_\ell}(\delta').
    \end{equation}

Work on $G_R(\delta)$. We first record that~\eqref{eq:block-recursion-R} implies, bounding the geometric sum and using~\eqref{eq:R-admissible},
    \begin{equation}
        \label{eq:margin}
        e_{b_i} \leq e_0+\frac{\bar{\varepsilon}_R(\delta)}{\bar{\beta}(R)}, \qquad\text{hence}\qquad e_{b_i}+\bar{\varepsilon}_R(\delta) \leq e_0+\frac{\bar{\beta}(R)+1}{\bar{\beta}(R)}\bar{\varepsilon}_R(\delta) \leq R.
    \end{equation}

    We prove by induction on $i\in\llbracket0,I(T)\rrbracket$ that $\sigma_R>b_i$ and~\eqref{eq:block-recursion-R} holds at rank $i$.

    \emph{Base case.} $b_0=0$ and $\sigma_R\geq1$ by \@gobble{rem:exit-time-facts}.(i);~\eqref{eq:block-recursion-R} at $i=0$ reads $e_0\leq e_0$.

    \emph{Inductive step.} Assume the claim at rank $i<I(T)$ and let $\tilde{Q}$ be the virtual sequence started at $Q_{b_i}$; by~\eqref{eq:margin}, $e_{b_i}\leq R$, so \@gobble{lem:virtual-flow-R} applies to $\mathcal{B}_i$. Suppose $\sigma_R\leq b_{i+1}$; since $\sigma_R>b_i$, we would have $t^\star:=\sigma_R\in\llbracket b_i+1,b_{i+1}\rrbracket$, and as $t^\star\leq\min\{b_{i+1},\sigma_R\}$, \@gobble{lem:tracking-R} gives $\|Q_{t^\star}-\tilde{Q}_{t^\star}\|_\mathrm{sp}\leq\varepsilon_{\mathcal{B}_i}(\delta')\leq\bar{\varepsilon}_R(\delta)$ while \@gobble{lem:virtual-flow-R}.(i) gives $\|\tilde{Q}_{t^\star}-Q^*_\Omega\|_\mathrm{sp}\leq e_{b_i}$. Hence, by~\eqref{eq:margin}, $e_{\sigma_R} \leq e_{b_i}+\bar{\varepsilon}_R(\delta) \leq R$, contradicting the definition~\eqref{eq:exit-time} of $\sigma_R$. Therefore $\sigma_R>b_{i+1}$; in particular $b_{i+1}\leq\min\{b_{i+1},\sigma_R\}$, so \@gobble{lem:tracking-R} at $k=b_{i+1}$ combined with \@gobble{lem:virtual-flow-R}.(ii) yields $e_{b_{i+1}} \leq \|\tilde{Q}_{b_{i+1}}-Q^*_\Omega\|_\mathrm{sp}+\|Q_{b_{i+1}}-\tilde{Q}_{b_{i+1}}\|_\mathrm{sp} \leq (1-\bar{\beta}(R))e_{b_i}+\varepsilon_{\mathcal{B}_i}(\delta')$, which, injected into~\eqref{eq:block-recursion-R} at rank $i$, gives it at rank $i+1$.

    \emph{Residual interval.} The last step gives $\sigma_R>b_{I(T)}$. If $\sigma_R\leq T$, the same argument on $\mathcal{B}_{\mathrm{res}}$ --- \@gobble{lem:tracking-R} with $\mathcal{K}=\mathcal{B}_{\mathrm{res}}$ and \@gobble{lem:virtual-flow-R}.(i) --- gives $e_{\sigma_R}\leq e_{b_{I(T)}}+\bar{\varepsilon}_R(\delta)\leq R$, again a contradiction. Hence $\sigma_R>T$ and the containment follows from the definition of $\sigma_R$.

\label{thm:sync-stoch-R-app}
    \phantomsection\hypertarget{proof:sync-stoch-R}{}
    Let $\delta\in(0,1)$ and $T\geq1$. Under \@gobble{assumption:lr}, let the sub-block budget $\kappa_0>0$ be arbitrary and let the radius $R\geq e_0$ satisfy the admissibility condition~\eqref{eq:R-admissible}. Then, with probability at least $1-\delta$, $\sup_{0\leq t\leq T}e_t \leq R$ and
    \begin{align*}
        e_T &\leq (1-\bar{\beta}(R))^{I(T)}e_0 + 2\left(1+2m(\kappa_0+\alpha_0)\right)\bar{w}(R)\sqrt{\frac{1}{2}\log\left(\frac{2|\mathcal{S}||\mathcal{A}|(I_{\max}+1)}{\delta}\right)}\\
        &\qquad \times\left(\sum_{i=0}^{I(T)-1}(1-\bar{\beta}(R))^{I(T)-1-i}\sqrt{\sum_{k\in \mathcal{B}_i}\alpha_k^2}+\sqrt{\sum_{k\in\mathcal{B}_{\mathrm{res}}}\alpha_k^2}\right),
    \end{align*}
    where $\bar{\beta}(R)$ and $\bar{w}(R)$ are the localized constants of \@gobble{def:localized-radii}, $I(T)\geq\left\lfloor\frac{\sum_{t<T}\alpha_t}{m(\kappa_0+\alpha_0)}\right\rfloor$ is the number of completed blocks and $I_{\max}\geq I(T)$.

\label{cor:sync-const-step-R}
    Under the assumptions of \@gobble{thm:sync-stoch-R-app}, let the step size be constant, $\alpha_t=\alpha\in(0,1)$, and set $C_\kappa := \sqrt{2}\left(1+2m(\kappa_0+\alpha)\right)$. If the radius $R\geq e_0$ satisfies
    \begin{equation}
        \label{eq:R-admissible-const}
        C_\kappa\,\bar{w}(R)\sqrt{m(\kappa_0+\alpha)\,\alpha\,\log\left(\frac{2|\mathcal{S}||\mathcal{A}|\left(\frac{\alpha T}{m\kappa_0}+1\right)}{\delta}\right)} \leq \frac{\bar{\beta}(R)}{\bar{\beta}(R)+1}\left(R-e_0\right),
    \end{equation}
    then~\eqref{eq:R-admissible} holds and, with probability at least $1-\delta$,
    \begin{align*}
        e_T &\leq \frac{1}{1-\bar{\beta}(R)}\left(1-\bar{\beta}(R)\right)^{\frac{\alpha T}{m(\kappa_0+\alpha)}}e_0\\
        &\qquad + \frac{(\bar{\beta}(R)+1)C_\kappa\bar{w}(R)}{\bar{\beta}(R)}\sqrt{m(\kappa_0+\alpha)\,\alpha\,\log\left(\frac{2|\mathcal{S}||\mathcal{A}|\left(\frac{\alpha T}{m\kappa_0}+1\right)}{\delta}\right)}.
    \end{align*}

With a constant step size, every sub-block has exactly $\lceil\kappa_0/\alpha\rceil$ indices, so $|\mathcal{B}_i|=m\lceil\kappa_0/\alpha\rceil$ and, using $\lceil\kappa_0/\alpha\rceil<\frac{\kappa_0+\alpha}{\alpha}$ and $\lfloor x\rfloor>x-1$, $I(T)>\frac{\alpha T}{m(\kappa_0+\alpha)}-1$; moreover $v_{\mathcal{B}_i}=|\mathcal{B}_i|\alpha^2\leq m(\kappa_0+\alpha)\alpha$ for every $i$, and the same bound holds for $v_{\mathcal{B}_{\mathrm{res}}}$ since $\mathcal{B}_{\mathrm{res}}\subseteq\mathcal{B}_{I(T)}$. Hence, for every interval $\mathcal{K}$ among the $\mathcal{B}_i$ and $\mathcal{B}_{\mathrm{res}}$,
    \begin{equation*}
        \varepsilon_\mathcal{K}(\delta') \leq 2\left(1+2m(\kappa_0+\alpha)\right)\bar{w}(R)\sqrt{\frac{1}{2}m(\kappa_0+\alpha)\alpha\log\left(\frac{2|\mathcal{S}||\mathcal{A}|\left(\frac{\alpha T}{m\kappa_0}+1\right)}{\delta}\right)},
    \end{equation*}
    which is the left-hand side of~\eqref{eq:R-admissible-const}, so~\eqref{eq:R-admissible-const} implies~\eqref{eq:R-admissible}. \@gobble{thm:sync-stoch-R-app} then applies, and the noise term is summed using $\sum_{i=0}^{I(T)-1}(1-\bar{\beta}(R))^{I(T)-1-i}\leq\frac{1}{\bar{\beta}(R)}$, so that the bracket is at most $\left(\frac{1}{\bar{\beta}(R)}+1\right)\sqrt{m(\kappa_0+\alpha)\alpha}$. Finally $1-\bar{\beta}(R)\in(0,1)$ and $I(T)>\frac{\alpha T}{m(\kappa_0+\alpha)}-1$ give the prefactor $\frac{1}{1-\bar{\beta}(R)}$ on the contraction term.

\label{lem:ep_update}
    \begin{enumerate}[label=(\roman*)]
        \item On $\{\ell_j<+\infty\}$ we have $N_j(s,a)=B_j$ for every pair at exit, and
        \begin{equation}
            \label{eq:ep_update}
            Q_{j+1}=F_j(Q_j)+\alpha_jW_{j+1},\qquad F_j(Q):=(1-\alpha_j)Q+\alpha_j \mathcal{T}_\Omega(Q),
        \end{equation}
        where, with $t_1(s,a)<\dots<t_{B_j}(s,a)$ the first $B_j$ visit times to $(s,a)$ in the extended trajectory of epoch $j$, counted from the beginning $n_j$ of the epoch,
        \begin{equation}
            \label{eq:ep_noise}
            \begin{aligned}
                W_{j+1}(s,a)&=\frac{1}{B_j}\sum_{l=1}^{B_j}Z^{(j)}_l(s,a),\\
                Z^{(j)}_l(s,a)&:=\Omega^*(Q_j)\big(\tilde{s}^{(j)}_{t_l(s,a)+1}\big)-\mathbb{E}_{s'\sim p(\cdot|s,a)}\big[\Omega^*(Q_j)(s')\big].
            \end{aligned}
        \end{equation}
        \item Every $Q_j$ is a well-defined $\mathcal{G}_j$-measurable random vector of $\mathbb{R}^{\mathcal{S}\times\mathcal{A}}$, with $\|Q_j\|_\infty<+\infty$ everywhere. Consequently $\pi_j$ is a well-defined policy and the extended trajectory of \@gobble{conv:ep_extended} is a well-defined Markov chain, for every $j$ and on every path.
    \end{enumerate}

\label{lem:ep_cover_time}
    Let $j\geq0$, let $u\geq0$ be a radius and let $\delta'\in(0,1)$. Set
    \begin{equation}
        \label{eq:ep_qr}
        \mathcal{D}_j(u) := \left\{\|Q_j\|_\mathrm{asp}\leq u\right\}\in\mathcal{G}_j, \qquad q(u) := \beta_m\,\gamma_\Omega(u)^m\,\eta_{\min},
    \end{equation}
    \begin{equation}
        \label{eq:ep_KL}
        K(u,\delta') := \left\lceil\frac{\left(\sqrt{B_j}+\sqrt{\iota(\delta')}\right)^2}{q(u)}\right\rceil,
        \qquad L(u,\delta') := m\,K(u,\delta')+1,
        \qquad \iota(\delta') := \log\left(\frac{|\mathcal{S}||\mathcal{A}|}{\delta'}\right).
    \end{equation}
    Under~\eqref{eq:P1}, $q(u)>0$ and, almost surely,
    \begin{equation}
        \label{eq:ep_conditional_length}
        \mathbb{P}\left(\left\{\ell_j>L(u,\delta')\right\}\cap\mathcal{D}_j(u)\ \middle|\ \mathcal{G}_j\right)\ \leq\ \delta'\,\mathbb{1}_{\mathcal{D}_j(u)}.
    \end{equation}
    Moreover $L(u,\delta')\geq m|\mathcal{S}||\mathcal{A}|B_j$. In particular, for $R\geq e_0$, the coverage constant and the localized length
    \begin{equation}
        \label{eq:ep_length_bound}
        q_R:=q(A_R)=\gamma_\Omega(A_R)\,\tilde\beta_m(A_R)\,\eta_{\min},\qquad
        L_j(\delta') := L(A_R,\delta') = m\left\lceil\frac{\left(\sqrt{B_j}+\sqrt{\iota(\delta')}\right)^2}{q_R}\right\rceil+1
    \end{equation}
    satisfy $\mathbb{P}\left(\left\{\ell_j>L_j(\delta')\right\}\cap\{j<\sigma_R\}\mid\mathcal{G}_j\right)\leq\delta'\mathbb{1}_{\{j<\sigma_R\}}$ almost surely.

Since $\mathcal{D}_j(u)\in\mathcal{G}_j$, it suffices to prove $\mathbb{P}(\ell_j>L(u,\delta')\mid\mathcal{G}_j)\leq\delta'$ almost surely on $\mathcal{D}_j(u)$; we work under a regular conditional probability given $\mathcal{G}_j$ and fix an outcome in $\mathcal{D}_j(u)$. All the constants $q(u)>0$, $K:=K(u,\delta')$ and $L(u,\delta')$ are deterministic, $u$ being deterministic; positivity of $q(u)$ is~\eqref{eq:P1} at the deterministic radius $u$.

    By \@gobble{lem:ep_update}.(ii), the extended trajectory of epoch $j$ is well defined and, conditionally on $\mathcal{G}_j$, is a time-homogeneous Markov chain with kernel $K_{\pi_j}$; the conditioning is legitimate because $\mathcal{D}_j(u)\in\mathcal{G}_j\subseteq\widetilde{\mathcal{H}}^{(j)}_n$. On $\mathcal{D}_j(u)$, \@gobble{def:mixing_objects}.(iii) applied at radius $u$ gives $\pi_j(a|s)\geq\gamma_\Omega(u)\mu(a|s)$ for all $(s,a)$, so \@gobble{lem:mixing-properties-of-regularization}.(iii) applied with $\pi_1=\cdots=\pi_m=\pi_j$ gives, for every $n\geq0$ and every $(s,a)\in\mathcal{S}\times\mathcal{A}$,
    \begin{equation}
        \label{eq:ep_coverage}
        \mathbb{P}\left(\left(\tilde{s}^{(j)}_{n+m},\tilde{a}^{(j)}_{n+m}\right)=(s,a)\ \middle|\ \widetilde{\mathcal{H}}^{(j)}_n\right)
        =K_{\pi_j}^m\big(s,a\,|\,\tilde{s}^{(j)}_n,\tilde{a}^{(j)}_n\big)
        \ \geq\ \beta_m\,\gamma_\Omega(u)^m\,\eta(s,a)\ \geq\ q(u).
    \end{equation}

    Fix $(s,a)$ and set $Z_l:=\mathbb{1}_{\{(\tilde{s}^{(j)}_{lm},\tilde{a}^{(j)}_{lm})=(s,a)\}}\in[0,1]$ for $l\in\llbracket1,K\rrbracket$, adapted to $\mathcal{G}^{\mathrm{sub}}_l:=\widetilde{\mathcal{H}}^{(j)}_{lm}$. Consecutive sub-sampling instants being exactly $m$ steps apart, \eqref{eq:ep_coverage} gives $\mathbb{E}[Z_l\mid\mathcal{G}^{\mathrm{sub}}_{l-1}]\geq q(u)$, so the predictable mean satisfies $\bar{S}\geq Kq(u)$ deterministically. The exact multiplicative-Chernoff form~\eqref{eq:exact-chernoff} of \@gobble{lem:self-bounding}, applied with increment bound $b=1$, $a=Kq(u)$ and $c=B_j$, all deterministic, gives
    \begin{equation}
        \label{eq:ep_chernoff}
        \mathbb{P}\left(\sum_{l=1}^KZ_l<B_j\ \middle|\ \mathcal{G}_j\right)\leq\exp\left(-B_j\,h(\theta)\right),
        \qquad \theta:=\frac{Kq(u)}{B_j},\quad h(\theta):=\theta-1-\log\theta,
    \end{equation}
    the hypothesis $c<a$ holding since $Kq(u)\geq(\sqrt{B_j}+\sqrt{\iota(\delta')})^2>B_j$.

    Now $h(\theta)\geq(\sqrt\theta-1)^2$ for $\theta\geq1$: both sides vanish at $\theta=1$ and $h'(\theta)=1-\theta^{-1}\geq1-\theta^{-1/2}$ there, the right-hand side being the derivative of $\theta\mapsto(\sqrt\theta-1)^2$. By the choice of $K$, $\theta\geq(1+\sqrt{\iota(\delta')/B_j})^2$, hence $B_jh(\theta)\geq B_j(\sqrt\theta-1)^2\geq\iota(\delta')$ and the right-hand side of~\eqref{eq:ep_chernoff} is at most $\delta'/(|\mathcal{S}||\mathcal{A}|)$.

    A union bound over the $|\mathcal{S}||\mathcal{A}|$ pairs shows that, with conditional probability at least $1-\delta'$, every pair is visited at least $B_j$ times among the instants $\{m,2m,\dots,Km\}\subseteq\llbracket0,mK\rrbracket$, so $\ell_j\leq mK+1=L(u,\delta')$. This is~\eqref{eq:ep_conditional_length}.

    Finally $q(u)\leq\eta_{\min}\leq(|\mathcal{S}||\mathcal{A}|)^{-1}$, so $K(u,\delta')\geq|\mathcal{S}||\mathcal{A}|B_j$ and $L(u,\delta')\geq m|\mathcal{S}||\mathcal{A}|B_j$. For the last claim, \@gobble{rem:ep_exit_time} gives $\{j<\sigma_R\}\subseteq\mathcal{D}_j(A_R)$, both events belonging to $\mathcal{G}_j$; apply~\eqref{eq:ep_conditional_length} with the deterministic radius $u=A_R$ and intersect with $\{j<\sigma_R\}$.

\label{lem:ep_counts}
    Let $T\geq 0$, $\underline{B}:=\min_jB_j\geq1$. Then:
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Deterministic upper bounds}: $\ell_j\geq|\mathcal{S}||\mathcal{A}|B_j$, hence $J(T)\leq J_{\max}(T):=\left\lfloor\frac{T}{|\mathcal{S}||\mathcal{A}|\underline{B}}\right\rfloor$ and $I(T)\leq I_{\max}(T):=\left\lfloor\frac{J_{\max}(T)}{m}\right\rfloor$.
        \item \emph{From epochs to blocks}: $I(T) > \frac{\sum_{j<J(T)}\alpha_j}{m(\kappa_0+\alpha_0)}-1$, i.e.\ $I(T)\geq\left\lfloor\frac{\sum_{j<J(T)}\alpha_j}{m(\kappa_0+\alpha_0)}\right\rfloor$. If $\alpha_j\equiv\alpha$, every block contains exactly $m\lceil\kappa_0/\alpha\rceil$ epochs and $I(T)=\left\lfloor\frac{J(T)}{m\lceil\kappa_0/\alpha\rceil}\right\rfloor$.
        \item \emph{From transitions to epochs}: set $J^-(T):=\max\left\{J\mid\sum_{j<J}L_j(\delta')\leq T\right\}$. If $\ell_j\leq L_j(\delta')$ for every $j<\min\{\sigma_R,J_{\max}(T)\}$ and $\sigma_R>J(T)$, then $J(T)\geq J^-(T)$. In particular for $\alpha_j\equiv\alpha$, $B_j\equiv B$, writing $L(\delta')$ for the common value,
        \begin{equation}
            \label{eq:ep_I_of_T}
            J(T)\geq\left\lfloor\frac{T}{L(\delta')}\right\rfloor,\qquad
            I(T)\geq\left\lfloor\frac{\alpha T}{m(\kappa_0+\alpha)L(\delta')}-\frac{\alpha}{m(\kappa_0+\alpha)}\right\rfloor.
        \end{equation}
    \end{enumerate}

\label{lem:ep_virtual_flow}
    Let $i$ be such that $e_{b_i}\leq R$. Then, pathwise:
    \begin{enumerate}[label=(\roman*)]
        \item $\|\tilde{Q}_j-Q^*_\Omega\|_\mathrm{sp}\leq e_{b_i}$ for every $j\geq b_i$;
        \item $\|\tilde{Q}_{b_{i+1}}-Q^*_\Omega\|_\mathrm{sp}\leq(1-\bar{\beta}(R))\,e_{b_i}$.
    \end{enumerate}

\label{lem:ep_noise}
    Fix $x=(s,a)$ and let $\mathcal{K}^{(j)}_l:=\sigma\left(\widetilde{\mathcal{H}}^{(j)}_{t_l(x)},\tilde{s}^{(j)}_{t_l(x)+1}\right)$ for $l\in\llbracket1,B_j\rrbracket$, $\mathcal{K}^{(j)}_0:=\mathcal{G}_j$. Then:
    \begin{enumerate}[label=(\roman*)]
        \item $\mathcal{K}^{(j)}_0\subseteq\dots\subseteq\mathcal{K}^{(j)}_{B_j}\subseteq\mathcal{G}_{j+1}\subseteq\mathcal{K}^{(j+1)}_0$, so the concatenation over $j$ is a filtration at fixed $x$; in particular $W_{j+1}$ is $\mathcal{G}_{j+1}$-measurable;
        \item $\mathbb{E}[\widehat{Z}^{(j)}_l(x)\mid\mathcal{K}^{(j)}_{l-1}]=0$; consequently $\mathbb{E}[\widehat{W}_{j+1}\mid\mathcal{G}_j]=0$;
        \item $\widehat{Z}^{(j)}_l(x)$ lies in a $\mathcal{G}_j$-measurable interval of length $\mathbb{1}_{\{j<\sigma_R\}}\|\Omega^*(Q_j)\|_{\mathcal{S},\mathrm{sp}}\leq\bar{w}(R)$.
    \end{enumerate}

\label{lem:ep_noise_epoch}
    For every $j$ and $\delta'\in(0,1)$, with probability at least $1-\delta'$,
    \begin{equation}
        \label{eq:ep_noise_bound}
        \left\|\widehat{W}_{j+1}\right\|_\infty\leq\bar{U}_j(\delta'):=\bar{w}(R)\sqrt{\frac{1}{2B_j}\log\left(\frac{2|\mathcal{S}||\mathcal{A}|}{\delta'}\right)},
        \qquad\text{hence}\qquad\left\|\widehat{W}_{j+1}\right\|_\mathrm{sp}\leq2\bar{U}_j(\delta').
    \end{equation}

\label{lem:ep_block_martingale}
    Fix $i$ and define $\widehat{U}^{(i)}_{b_i}:=0$, $\widehat{U}^{(i)}_{j+1}:=\widehat{U}^{(i)}_j+\alpha_j\widehat{W}_{j+1}$. Then for every $\delta'\in(0,1)$, with probability at least $1-\delta'$,
    \begin{equation}
        \label{eq:ep_block_martingale_bound}
        \max_{b_i\leq j\leq b_{i+1}}\left\|\widehat{U}^{(i)}_j\right\|_\infty\leq\bar{V}_i(\delta'):=\bar{w}(R)\sqrt{\frac{1}{2}\left(\sum_{j\in\mathcal{B}_i}\frac{\alpha_j^2}{B_j}\right)\log\left(\frac{2|\mathcal{S}||\mathcal{A}|}{\delta'}\right)}.
    \end{equation}
    The same holds with $\mathcal{B}_i$ replaced by any prefix, in particular by $\mathcal{B}_{\mathrm{res}}$.

Fix $x$ and concatenate chronologically the increments $\left(\frac{\alpha_j}{B_j}\widehat{Z}^{(j)}_l(x)\right)_{j\in\mathcal{B}_i,\,l\leq B_j}$, adapted to the filtration of \@gobble{lem:ep_noise}.(i). They are martingale differences by (ii), and by (iii) the $l$-th increment of epoch $j$ has predictable range of deterministic length $\frac{\alpha_j}{B_j}\bar{w}(R)$. The total number of increments $\sum_{j\in\mathcal{B}_i}B_j$ is deterministic (\@gobble{lem:ep_update}) and
    \begin{equation*}
        \sum_{j\in\mathcal{B}_i}\sum_{l=1}^{B_j}\left(\frac{\alpha_j}{B_j}\bar{w}(R)\right)^2=\bar{w}(R)^2\sum_{j\in\mathcal{B}_i}\frac{\alpha_j^2}{B_j}.
    \end{equation*}
    The partial sums at epoch boundaries are exactly $\widehat{U}^{(i)}_j(x)$, so \@gobble{lem:azuma_range} with $u=\bar{V}_i(\delta')$ and a union bound over the pairs give~\eqref{eq:ep_block_martingale_bound}.

\label{lem:ep_tracking}
    Let $i$ be such that $e_{b_i}\leq R$, let $\tilde{Q}$ be the virtual sequence started at $Q_{b_i}$ and $E_j:=Q_j-\tilde{Q}_j$. Then for every $j\in\mathcal{B}_i\cup\{b_{i+1}\}$ with $j\leq\sigma_R$:
    \begin{enumerate}[label=(\roman*)]
        \item on $\bigcap_{k\in\mathcal{B}_i}\{\|\widehat{W}_{k+1}\|_\infty\leq\bar{U}_k(\delta')\}$: $\ \|E_j\|_\mathrm{sp}\leq\varepsilon^{\mathrm{bat}}_i(\delta'):=2\sum_{k\in\mathcal{B}_i}\alpha_k\bar{U}_k(\delta')$;
        \item on $\{\max_k\|\widehat{U}^{(i)}_k\|_\infty\leq\bar{V}_i(\delta')\}$: $\ \|E_j\|_\mathrm{sp}\leq\varepsilon^{\mathrm{mg}}_i(\delta'):=2\left(1+2\sum_{k\in\mathcal{B}_i}\alpha_k\right)\bar{V}_i(\delta')$.
    \end{enumerate}
    Both hold verbatim on any prefix, in particular on $\mathcal{B}_{\mathrm{res}}$.

For $k\in\mathcal{B}_i$ with $k<\sigma_R$, $\widehat{W}_{k+1}=W_{k+1}$ and $\ell_k<+\infty$ (\@gobble{prop:ep_wellposed}), so~\eqref{eq:ep_update} applies. Subtracting the virtual recursion and using the average-path identity of \@gobble{lem:mixing-properties-of-regularization}.(i), i.e.\ $\mathcal{T}_\Omega(Q_k)-\mathcal{T}_\Omega(\tilde{Q}_k)=\bar{K}_kE_k$ with $\bar{K}_k:=K_{\bar{\pi}_{\Omega,[Q_k,\tilde{Q}_k]}}$,
    \begin{equation}
        \label{eq:ep_err_rec}
        E_{k+1}=M_kE_k+\alpha_k\widehat{W}_{k+1},\qquad M_k:=(1-\alpha_k)I+\alpha_k\bar{K}_k,
    \end{equation}
    with $M_k$ row-stochastic, hence span non-expansive (\@gobble{lem:row-stochastic-span}).

    \emph{(i)}. $\|E_{k+1}\|_\mathrm{sp}\leq\|E_k\|_\mathrm{sp}+2\alpha_k\bar{U}_k(\delta')$ by~\eqref{eq:ep_noise_bound}, and an immediate induction from $E_{b_i}=0$ concludes.

    \emph{(ii)}. The recursion~\eqref{eq:ep_err_rec} has the same form as~\eqref{eq:sync-err-rec-R}, so the decomposition $E_k=\widehat{R}_k+\widehat{U}^{(i)}_k$ in the proof of \@gobble{lem:tracking-R}, with $\widehat{U}^{(i)}$ and $\bar{V}_i(\delta')$ in place of $\widehat{U}^{(\mathcal{K})}$ and $\bar{U}_\mathcal{K}(\delta')$, gives $\|E_j\|_\mathrm{sp}\leq\varepsilon^{\mathrm{mg}}_i(\delta')$.

\label{lem:ep_good_event}
    The event
    \begin{align}
        \mathcal{E}_R(\delta)&:=\bigcap_{j<J_{\max}(T)}\left\{\left\|\widehat{W}_{j+1}\right\|_\infty\leq\bar{U}_j(\delta')\right\}
        \cap\bigcap_{i\leq I_{\max}(T)}\left\{\max_{b_i\leq j\leq b_{i+1}}\left\|\widehat{U}^{(i)}_j\right\|_\infty\leq\bar{V}_i(\delta')\right\}\notag\\
        &\qquad\cap\bigcap_{j<J_{\max}(T)}\left(\{j\geq\sigma_R\}\cup\left\{\ell_j\leq L_j(\delta')\right\}\right)
        \label{eq:ep_good_event}
    \end{align}
    satisfies $\mathbb{P}(\mathcal{E}_R(\delta))\geq1-\delta$.

\label{prop:ep_no_escape}
    Let $R\geq e_0$ satisfy the \emph{radius admissibility condition}
    \begin{equation}
        \label{eq:ep_R_admissible}
        \bar{\varepsilon}_R(\delta)\leq\frac{\bar{\beta}(R)}{\bar{\beta}(R)+1}\left(R-e_0\right).
    \end{equation}
    Then, on $\mathcal{E}_R(\delta)$, $\sigma_R>J(T)$; in particular $\sup_{0\leq j\leq J(T)}e_j\leq R$ and $\ell_j\leq L_j(\delta')$ for every $j<J(T)$, and for every $0\leq i\leq I(T)$,
    \begin{equation}
        \label{eq:ep_block_recursion}
        e_{b_i}\leq(1-\bar{\beta}(R))^ie_0+\sum_{\ell=0}^{i-1}(1-\bar{\beta}(R))^{i-1-\ell}\varepsilon_\ell(\delta').
    \end{equation}

\label{thm:ep_main}
    Let $\delta\in(0,1)$ and $T\geq 0$. Under \@gobble{assumption:lr}, let $\kappa_0>0$ be arbitrary and let $R\geq e_0$ satisfy the admissibility condition~\eqref{eq:ep_R_admissible}. Then, with probability at least $1-\delta$, $\sup_{0\leq j\leq J(T)}e_j\leq R$ and
    \begin{equation}
        \label{eq:ep_main_bound}
        e_{J(T)}\leq(1-\bar{\beta}(R))^{I(T)}e_0
        +\sum_{i=0}^{I(T)-1}(1-\bar{\beta}(R))^{I(T)-1-i}\varepsilon_i(\delta')+\varepsilon_{\mathrm{res}}(\delta'),
    \end{equation}
    where $J(T)$ and $I(T)$ are bounded below in \@gobble{lem:ep_counts}.(iii). Explicitly, with $\iota_1:=\log\left(\frac{6|\mathcal{S}||\mathcal{A}|(J_{\max}(T)+1)}{\delta}\right)$,
    \begin{equation}
        \label{eq:ep_eps_explicit}
        \varepsilon_i(\delta')=\bar{w}(R)\sqrt{2\iota_1}\,\min\left\{\ \sum_{j\in\mathcal{B}_i}\frac{\alpha_j}{\sqrt{B_j}},\ \ \left(1+2\sum_{j\in\mathcal{B}_i}\alpha_j\right)\sqrt{\sum_{j\in\mathcal{B}_i}\frac{\alpha_j^2}{B_j}}\ \right\}.
    \end{equation}

\label{cor:ep_alpha_one}
    Take $\alpha_j\equiv1$, $B_j\equiv B$, and define the blocks directly as $\mathcal{B}_i:=\llbracket im,(i+1)m-1\rrbracket$, so that $I(T)=\lfloor J(T)/m\rfloor$. Then $F_j=\mathcal{T}_\Omega$, the block map is $\mathcal{T}^m_\Omega$, and \@gobble{lem:ep_virtual_flow} holds with $\bar{\beta}(R)$ replaced by $\tilde\beta_m(A_R)=\beta_m\gamma_\Omega(A_R)^{m-1}$, with no sub-block budget $\kappa_0$ and no probability $p_m$. With $\bar{U}:=\bar{w}(R)\sqrt{\iota_1/(2B)}$, the batch bound gives $\varepsilon_i(\delta')\leq2m\bar{U}$ and $\varepsilon_{\mathrm{res}}(\delta')\leq2m\bar{U}$, condition~\eqref{eq:ep_R_admissible} becomes
    \begin{equation}
        \label{eq:ep_admissible_alpha_one}
        2m\bar{U}\leq\frac{\tilde{\beta}_m(A_R)}{1+\tilde{\beta}_m(A_R)}\left(R-e_0\right),
    \end{equation}
    and with probability at least $1-\delta$,
    \begin{equation}
        \label{eq:ep_bound_alpha_one}
        \sup_{0\leq j\leq J(T)}e_j\leq R,\qquad
        e_{J(T)}\leq\left(1-\tilde{\beta}_m(A_R)\right)^{I(T)}e_0+\frac{(1+\tilde{\beta}_m(A_R))2m\bar{U}}{\tilde{\beta}_m(A_R)}.
    \end{equation}

With $\alpha_j=1$, $\tilde{Q}_j=\mathcal{T}^{j-b_i}_\Omega(Q_{b_i})$. By \@gobble{cor:T_omega_props}, $\mathcal{T}^k_\Omega(Q^*_\Omega)=Q^*_\Omega+k\rho^*_\Omega\mathbf{1}$, of action-span $\|Q^*_\Omega\|_\mathrm{asp}$. If $e_{b_i}\leq R$, span non-expansiveness gives $\|\tilde{Q}_j-Q^*_\Omega\|_\mathrm{sp}\leq e_{b_i}\leq R$, which is \@gobble{lem:ep_virtual_flow}.(i), hence $\|\tilde{Q}_j\|_\mathrm{asp}\leq A_R$, i.e.\ $R[\mathcal{T}_\Omega^k(Q_{b_i}),\mathcal{T}_\Omega^k(Q^*_\Omega)]\leq A_R$ for $k\in\llbracket0,m-1\rrbracket$ (\@gobble{def:mixing_objects}.(ii)). Since $\gamma_\Omega$ is non-increasing, \@gobble{lem:mixing-properties-of-regularization}.(iv) gives
    \begin{equation*}
        \left\|\mathcal{T}^m_\Omega(Q_{b_i})-\mathcal{T}^m_\Omega(Q^*_\Omega)\right\|_\mathrm{sp}\leq\left(1-\beta_m\gamma_\Omega(A_R)^{m-1}\right)e_{b_i},
    \end{equation*}
    which is \@gobble{lem:ep_virtual_flow}.(ii) with $\tilde{\beta}_m(A_R)$ in place of $\bar{\beta}(R)$; neither \@gobble{lem:pickup_synchronous} nor the probabilistic argument of \@gobble{lem:jacobian_bound_synchronous} is needed. \@gobble{prop:ep_no_escape} and \@gobble{thm:ep_main} then apply verbatim with $\tilde{\beta}_m(A_R)$ in place of $\bar{\beta}(R)$, the geometric sum being bounded by $1/\tilde{\beta}_m(A_R)$ and the residual block adding one copy of $2m\bar{U}$.

\label{rem:ep_behavior_mu}
    The update of \@gobble{alg:epoch_regularized_q_learning} is off-policy: its target $r(s,a)+\Omega^*(Q_j)(s')$ is an expectation under the greedy policy and does not sample the next action, so the noise analysis only uses that the successor of a visited pair $(s,a)$ is distributed as $p(\cdot|s,a)$ (\@gobble{lem:ep_noise}.(ii)), whatever the law of the action. Running the algorithm with actions $a_n\sim\mu(\cdot|s_n)$ is therefore covered by the same analysis, with $\gamma_\Omega$ replaced by $1$ in \@gobble{lem:ep_cover_time}: $q_R$ becomes $\beta_m\eta_{\min}$, $L$ becomes $m\lceil(\sqrt B+\sqrt\iota)^2/(\beta_m\eta_{\min})\rceil+1$ in \@gobble{thm:epoch-main-body}, and the sample complexity becomes $\tilde O\big(m^4\bar w^2/(\tilde\beta^3\cdot\beta_m\eta_{\min}\cdot\varepsilon^2)\big)$, the factor $\tilde\beta^3$ of the contraction being unchanged. Acting with the greedy policies thus costs at most a factor $\bar\gamma^m$ in coverage.

    Our criterion, uniform accuracy on all pairs of a tabular MDP, favors a fixed well-mixing behavior, and cannot credit what acting with the learned policy brings: the reward collected during learning, data concentrated where a good policy goes and, beyond the tabular setting, the stability of on-policy data distributions under function approximation \citep[\S11.3]{sutton2018reinforcement}. What the analysis does show is that regularization makes this choice safe: with a hard maximum, the greedy policy is deterministic and needs an added exploration mechanism, whereas under~\eqref{eq:P1} it explores by itself, at a quantified rate.

\label{thm:pl-epoch-main}
    Let $q:=q_\pi(\|Q^*_\Omega\|_\mathrm{asp}+2e_0)$, or $q:=q_\mu$ if the actions are drawn from $\mu$ instead of the greedy policies (\@gobble{rem:pl_behavior}). Let $J\geq H$, $\iota_H:=\log(4JH\bar S_H|\mathcal{A}|/\delta)$, $M:=h_1+H_{\mathrm{eff}}$ and $B(u):=2M^2\bar w^2\iota_H/u^2$. Run \@gobble{alg:epoch_regularized_q_planning} for $J$ epochs with a batch size $B\geq B(e_0)$. Then, with probability at least $1-\delta$, each epoch lasts at most $H\lceil(\sqrt B+\sqrt{\iota_H})^2/q\rceil$ transitions and
    \begin{equation}
        \label{eq:pl-epoch-main}
        \big\|Q_{J,0}-Q^*_\Omega\big\|_{\mathrm{sp},\mathcal{X}_0}\leq(1-\tilde\beta)^{\lfloor(H-h_1)/m\rfloor}\Delta_B+2M\bar w\sqrt{\frac{\iota_H}{2B}}.
    \end{equation}
    In particular, for $\varepsilon\in(0,e_0)$, the choices $H\geq h_1+m+H_{\mathrm{eff}}\log_+(2\Delta_B/\varepsilon)$, $J=H$ and $B=\lceil B(\varepsilon/2)\rceil$ give $\|Q_{J,0}-Q^*_\Omega\|_{\mathrm{sp},\mathcal{X}_0}\leq\varepsilon$, i.e.\ $\tilde O\big((h_1+H_{\mathrm{eff}})^4\,\bar w^2/(q\,\varepsilon^2)\big)$ sampled transitions.

\label{lem:pl_extension}
    Let $\mathcal{V}:=\mathcal{S}'\setminus\mathcal{S}_\infty$. The accessibility relation restricted to $\mathcal{V}$ has no directed cycle, and $Q^*_\Omega$ has a unique extension to $\mathcal{S}'\times\mathcal{A}$ such that
    \begin{equation}
        \label{eq:pl_extension}
        \mathcal{T}_\Omega(Q^*_\Omega)=Q^*_\Omega+\rho^*_\Omega\mathbf{1} \qquad\text{on }\mathcal{S}'\times\mathcal{A}.
    \end{equation}
    Shifting $Q^*_\Omega$ by a constant on $\mathcal{S}_\infty$ shifts its extension by the same constant.

If $s\in\mathcal{V}\cap\mathcal{S}_j$ lay on a cycle of length $\ell\geq1$ within $\mathcal{V}$, then $s\in\mathcal{S}_{j+\ell i}$ for every $i\geq0$, hence $s\in\mathcal{S}_h=\mathcal{S}_\infty$ for some $h\geq h_1$, a contradiction. The subgraph induced on $\mathcal{V}$ is therefore acyclic, and its vertices admit a topological order in which every successor of $s\in\mathcal{V}$ lies either in $\mathcal{S}_\infty$ or later in the order. Defining, along the reverse of that order,
    \begin{equation*}
        Q^*_\Omega(s,a):=r(s,a)-\rho^*_\Omega+\sum_{s'}p(s'|s,a)\,\Omega^*(Q^*_\Omega)(s'), \qquad s\in\mathcal{V},
    \end{equation*}
    each right-hand side only involves values already defined, which gives existence and uniqueness. The last claim follows from the translation equivariance of $\Omega^*$ (\@gobble{lem:omega_star_props}.(iii)).

\label{lem:pl_avg_path_depth}
    Let $Q,Q'\in\mathbb{R}^{\mathcal{X}_{h+1}}$ and let $\bar{\pi}:=\bar{\pi}_{\Omega,[Q,Q']}$ be the average-path policy of \@gobble{def:mixing_objects}.(i). Then
    \begin{equation*}
        \mathcal{T}_{\Omega,h}(Q)-\mathcal{T}_{\Omega,h}(Q')=K^{(h)}_{\bar{\pi}}\left(Q-Q'\right), \qquad K^{(h)}_{\bar{\pi}}(s',a'|s,a):=p(s'|s,a)\,\bar{\pi}(a'|s'),
    \end{equation*}
     where $K^{(h)}_{\bar{\pi}}$, the restriction of the state-action kernel $K_{\bar\pi}$ to $\mathcal{X}_h\times\mathcal{X}_{h+1}$, is row-stochastic from $\mathcal{X}_h$ to $\mathcal{X}_{h+1}$, and $\bar{\pi}\geq\gamma_\Omega(R[Q,Q'])\,\mu$ on $\mathcal{X}_{h+1}$.

By \@gobble{lem:pl_restriction}, $Q^*_{\Omega,l}=\mathcal{T}_{\Omega,l}(Q^*_{\Omega,l+1})$ and $V_l:=Q^*_\Omega|_{\mathcal{X}_l}+(H-l)\rho^*_\Omega\mathbf{1}$ satisfies $V_l=\mathcal{T}_{\Omega,l}(V_{l+1})$ for every $l<H$, with $V_H=Q^*_\Omega|_{\mathcal{X}_H}$. \@gobble{lem:pl_avg_path_depth} gives $Q^*_{\Omega,l}-V_l=K^{(l)}_{\pi^{(l)}}(Q^*_{\Omega,l+1}-V_{l+1})$ with $\pi^{(l)}:=\bar{\pi}_{\Omega,[Q^*_{\Omega,l+1},Q^*_\Omega]}$, the greedy policies being invariant under constants. Unrolling from $l=h$ to $l=H$,
    \begin{equation*}
        Q^*_{\Omega,h}-Q^*_\Omega|_{\mathcal{X}_h}-(H-h)\rho^*_\Omega\mathbf{1}=K_{h:H}\big(Q_B-Q^*_\Omega\big)\big|_{\mathcal{X}_H}.
    \end{equation*}
    $K_{h:H}$ is row-stochastic, hence non-expansive in span (\@gobble{lem:row-stochastic-span}), and the span annihilates constants, whence the first claim. The other two follow from $\|\cdot\|_\mathrm{asp}\leq\|\cdot\|_\mathrm{sp}$, the invariance of $\|\cdot\|_\mathrm{asp}$ under constants and the triangle inequality.

\label{lem:pl_master}
    Let $0\leq h_0\leq h_e\leq H$, let $Q_l\in\mathbb{R}^{\mathcal{X}_l}$ for $l\in\llbracket h_0,h_e\rrbracket$, with residuals
    \begin{equation}
        \label{eq:pl_residual}
        r_l:=Q_l-\mathcal{T}_{\Omega,l}(Q_{l+1}), \qquad l\in\llbracket h_0,h_e-1\rrbracket,
    \end{equation}
    and assume $\|Q_l\|_\mathrm{asp}\leq A$ for $l\in\llbracket h_0+1,h_e\rrbracket$, with $A\geq A_{\Delta_B}$. Then, writing $\tilde{\beta}:=\tilde{\beta}_m(A)$,
    \begin{equation}
        \label{eq:pl_master}
        \begin{aligned}
            \big\|Q_{h_0}-Q^*_{\Omega,h_0}\big\|_\mathrm{sp}
            &\leq(1-\tilde{\beta})^{n(h_0,h_e-h_0)}\big\|Q_{h_e}-Q^*_{\Omega,h_e}\big\|_\mathrm{sp}+\sum_{l=h_0}^{h_e-1}(1-\tilde{\beta})^{n(h_0,l-h_0)}\|r_l\|_\mathrm{sp}\\
            &\leq(1-\tilde{\beta})^{n(h_0,h_e-h_0)}\big\|Q_{h_e}-Q^*_{\Omega,h_e}\big\|_\mathrm{sp}+2M(h_0,A)\max_{h_0\leq l<h_e}\|r_l\|_\infty.
        \end{aligned}
    \end{equation}

Let $e_l:=Q_l-Q^*_{\Omega,l}$. By~\eqref{eq:pl_residual}, the definition of the planning solution and \@gobble{lem:pl_avg_path_depth},
    \begin{equation*}
        e_l=r_l+\mathcal{T}_{\Omega,l}(Q_{l+1})-\mathcal{T}_{\Omega,l}(Q^*_{\Omega,l+1})=r_l+K^{(l)}_{\pi^{(l)}}e_{l+1}, \qquad \pi^{(l)}:=\bar{\pi}_{\Omega,[Q_{l+1},Q^*_{\Omega,l+1}]}.
    \end{equation*}
    Unrolling from $h_0$ to $h_e$ gives $e_{h_0}=K_{h_0:h_e}e_{h_e}+\sum_{l=h_0}^{h_e-1}K_{h_0:l}\,r_l$. By \@gobble{lem:pl_uniform_bounds}, $R[Q_{l+1},Q^*_{\Omega,l+1}]\leq\max\{A,A_{\Delta_B}\}=A$, so every $\pi^{(l)}$ dominates $\gamma_\Omega(A)\mu$ (\@gobble{lem:pl_avg_path_depth}) and \@gobble{lem:pl_product} applies to each product. The triangle inequality gives the first bound, and $\|\cdot\|_\mathrm{sp}\leq2\|\cdot\|_\infty$ together with \@gobble{lem:pl_geometric_sum} gives the second.

\label{cor:pl_horizon_bias}
    For every $h\in\llbracket0,H\rrbracket$,
    \begin{equation}
        \label{eq:pl_horizon_bias}
        \big\|Q^*_{\Omega,h}-Q^*_\Omega\big\|_{\mathrm{sp},\mathcal{X}_h}\leq\left(1-\tilde{\beta}_m(A_{\Delta_B})\right)^{n(h,H-h)}\Delta_B,
    \end{equation}
    and the right-hand side is at most $\varepsilon$ as soon as
    \begin{equation}
        \label{eq:pl_depth}
        H\geq\max\{h,h_1\}+m+H_{\mathrm{eff}}(A_{\Delta_B})\log_+\left(\frac{\Delta_B}{\varepsilon}\right).
    \end{equation}

\label{lem:pl_coverage}
    Let $\mathcal{G}$ be a $\sigma$-algebra and let $(s_h,a_h)_{h<H}$ be a trajectory with $s_0\sim\xi$, $a_h\sim\pi_h(\cdot|s_h)$ and $s_{h+1}\sim p(\cdot|s_h,a_h)$, where the policies $\pi_h$ are $\mathcal{G}$-measurable and the trajectory is otherwise independent of $\mathcal{G}$. Let $E\in\mathcal{G}$ be an event on which $\pi_h\geq\gamma_h\mu$ for every $h$, with deterministic $\gamma_h\in[0,1]$, and write $\mathcal{F}_n:=\sigma(\mathcal{G},s_0,a_0,\dots,s_n,a_n)$. Then, almost surely on $E$, for every $h<H$ and $(s,a)\in\mathcal{X}_h$:
    \begin{enumerate}[label=(\roman*)]
        \item if $h\geq h_1+m$, $\mathbb{P}\big((s_h,a_h)=(s,a)\mid\mathcal{F}_{h-m}\big)\geq\big(\prod_{l=h-m+1}^{h}\gamma_l\big)\beta_m\,\eta(s,a)$;
        \item if $h<h_1+m$, $\mathbb{P}\big((s_h,a_h)=(s,a)\mid\mathcal{G}\big)\geq\big(\prod_{l=0}^{h}\gamma_l\big)\eta^{\mathrm{res}}_h(s,a)$.
    \end{enumerate}
    In particular, almost surely on $E$, $\mathbb{P}((s_h,a_h)=(s,a)\mid\mathcal{G})\geq q_\mu$ if $\gamma_h\equiv1$, and $\geq q_\pi(A)$ if $\gamma_h\equiv\gamma_\Omega(A)$.

\label{prop:pl_horizon_main}
    For every $h\leq H$,
    \begin{equation}
        \label{eq:pl-horizon-main}
        \big\|Q^*_{\Omega,h}-Q^*_\Omega\big\|_{\mathrm{sp},\mathcal{X}_h}\leq(1-\tilde\beta)^{\lfloor(H-\max\{h,h_1\})/m\rfloor}\,\Delta_B .
    \end{equation}
    In particular, \@gobble{alg:pl_backward_sync} returns $(Q^*_{\Omega,h})_{h=0}^H$ exactly after $\sum_{h<H}|\mathcal{S}_h||\mathcal{A}||\mathcal{S}_{h+1}|\leq H\bar S_H^2|\mathcal{A}|$ model queries, one query being an evaluation of $p(s'|s,a)$, and $Q^*_{\Omega,0}$ is $\varepsilon$-accurate for $Q^*_\Omega$ on $\mathcal{X}_0$ as soon as $H\geq h_1+m+H_{\mathrm{eff}}\log_+(\Delta_B/\varepsilon)$.

\label{thm:pl_epoch}
    Let $R\geq e_0$ satisfy the \emph{radius admissibility condition}
    \begin{equation}
        \label{eq:pl_admissible}
        e_0+2M(A_R)\max_{j<J}\bar{u}_j(R)\leq R.
    \end{equation}
    Then, with probability at least $1-\delta$, every epoch $j<J$ lasts at most $N_jH$ transitions, $\max_{h<H}\|Q_{j,h}-Q^*_\Omega\|_{\mathrm{sp},\mathcal{X}_h}\leq R$ for every $j\leq J$, and, for every $j\leq J$ and $h<H$,
    \begin{equation}
        \label{eq:pl_epoch_bound}
        \begin{aligned}
            \big\|Q_{j,h}-Q^*_{\Omega,h}\big\|_\mathrm{sp}
            &\leq\mathbb{1}_{\{j<H-h\}}\left(1-\tilde{\beta}_m(A_R)\right)^{n(h,j)}D_0\\
            &\quad+2\sum_{k=0}^{\min\{j,H-h\}-1}\left(1-\tilde{\beta}_m(A_R)\right)^{n(h,k)}\bar{u}_{j-1-k}(R).
        \end{aligned}
    \end{equation}
    In particular, the initialization has vanished exactly for $j\geq H-h$.

\label{lem:pl_reset_cover_time}
    Assume $H\geq h_1+m+1$ and let $K_0:=\lfloor(H-1-h_1)/m\rfloor\geq1$. For $j\geq0$, a deterministic radius $u\geq0$ and $\delta'\in(0,1)$, let $\mathcal{D}_j(u):=\{\|Q_j\|_\mathrm{asp}\leq u\}$, let $q^{\mathrm{res}}(u):=\beta_m\gamma_\Omega(u)^m\eta_{\min}$, or $q^{\mathrm{res}}(u):=\beta_m\eta_{\min}$ if the actions at depths $h\geq h_1$ are drawn from $\mu$ instead of $\pi_{\Omega,Q_j}$, let $\iota(\delta'):=\log(|\mathcal{S}_\infty||\mathcal{A}|/\delta')$ and
    \begin{equation}
        \label{eq:pl_reset_length}
        L^{\mathrm{res}}_j(u,\delta'):=H\left\lceil\frac{1}{K_0}\left\lceil\frac{\big(\sqrt{B_j}+\sqrt{\iota(\delta')}\big)^2}{q^{\mathrm{res}}(u)}\right\rceil\right\rceil.
    \end{equation}
    Then, almost surely, $\mathbb{P}\big(\{\ell_j>L^{\mathrm{res}}_j(u,\delta')\}\cap\mathcal{D}_j(u)\mid\mathcal{G}_j\big)\leq\delta'\,\mathbb{1}_{\mathcal{D}_j(u)}$. If moreover $H\geq2(h_1+m+1)$, then $L^{\mathrm{res}}_j(u,\delta')\leq2m\big\lceil(\sqrt{B_j}+\sqrt{\iota(\delta')})^2/q^{\mathrm{res}}(u)\big\rceil+H$.

\label{thm:pl_reset_learning}
    Let $H\geq h_1+m+1$. \@gobble{thm:ep_main}, under \@gobble{assumption:lr}, and \@gobble{cor:ep_alpha_one} hold for \@gobble{alg:pl_reset_learning}, with every constant computed on the MDP restricted to $\mathcal{S}_\infty$ and the epoch length $L_j(\delta')$ of \@gobble{lem:ep_cover_time} replaced by $L^{\mathrm{res}}_j(A_R,\delta')$. In particular, \@gobble{thm:epoch-main-body} holds with $L:=H\lceil\frac{1}{K_0}\lceil(\sqrt B+\sqrt\iota)^2/q^{\mathrm{res}}\rceil\rceil$, where $q^{\mathrm{res}}:=\bar\gamma\tilde\beta\eta_{\min}$, or $q^{\mathrm{res}}:=\beta_m\eta_{\min}$ if the actions at depths $h\geq h_1$ are drawn from $\mu$. For $H\geq2(h_1+m+1)$, this gives the sample complexity
    \begin{equation}
        \label{eq:pl_reset_complexity}
        \tilde{O}\left(\frac{m^4\,\bar{w}^2}{\tilde{\beta}^3\,q^{\mathrm{res}}\,\varepsilon^2}+\frac{mH}{\tilde{\beta}}\right),
    \end{equation}
    whose first term is $\tilde O\big(m^4\bar w^2/(\tilde\beta^3\cdot\beta_m\eta_{\min}\cdot\varepsilon^2)\big)$ under the behavior $\mu$ and $\tilde O\big(m^4\bar w^2/(\tilde\beta^3\cdot\bar\gamma\tilde\beta\eta_{\min}\cdot\varepsilon^2)\big)$ under the greedy behavior.

\label{thm:alpha}
    Let $\alpha\in\mathbb{R}$, $\tau>0$ and $\mu$ have full support.
    \begin{enumerate}[label=(\roman*)]
        \item \emph{Domain.} $\mathrm{dom}(\Omega_{\alpha,s})=\Delta(\mathcal{A})$ for $\alpha>0$ and $\{\pi_s>0\}$ for $\alpha\leq0$; $\Omega_{\alpha,s}$ is proper and closed, and \@gobble{assumption:reference_policy_general} holds with $\tilde{\pi}=\mu$.
        \item \emph{Strong convexity} (Pinsker's inequality at $\alpha=1$). $\Omega_{\alpha,s}$ is $\mu_{\min}^{(1-\alpha)_+}$-strongly convex with respect to $\|\cdot\|_1$ for $\alpha\leq2$, and strictly but not strongly convex for $\alpha>2$.
         \item \emph{Greedy policy and conjugate} \citep[Proposition~1]{roulet2025loss}. For $\alpha\neq1$,
        \begin{align}
            \label{eq:alpha_policy_1}
            \pi_{\Omega_\alpha,Q}(a|s)&=\mu(a|s)\left[1+\frac{(\alpha-1)\big(Q(s,a)-\zeta_s(Q_s)\big)}{\tau}\right]_+^{\frac{1}{\alpha-1}},\\
            \label{eq:alpha_policy_2}
            \Omega^*_\alpha(Q)(s)&=\frac{(\alpha-1)\langle\pi_{\Omega_\alpha,Q}(\cdot|s),Q_s\rangle+\zeta_s(Q_s)}{\alpha}\quad(\alpha\neq0),
        \end{align}
        where $\zeta_s(Q_s)$ is the unique normalizer making~\eqref{eq:alpha_policy_1} sum to one; the truncation is active only for $\alpha>1$. For any $a^*\in\operatorname*{arg\,max}_aQ(s,a)$,
        \begin{equation*}
            \max_aQ(s,a)-\tau\,\frac{\mu(a^*|s)^{1-\alpha}-1}{\alpha-1}\ \leq\ \zeta_s(Q_s)\ \leq\ \max_aQ(s,a),
        \end{equation*}
        so that $\zeta_s$ is computable by bisection.
        \item \emph{Domination profile.} $\gamma_{\Omega_\alpha}(R)\geq\exp_{2-\alpha}(-R/\tau)$. If $\alpha>1$ and $|\mathcal{A}|\geq2$, then $\gamma_{\Omega_\alpha}(R)=0$ for $R\geq\tau\mu_{\max}^{1-\alpha}/(\alpha-1)$, with $\mu_{\max}:=\max_{s,a}\mu(a|s)$. Hence~\eqref{eq:P1} holds if and only if $\alpha\leq1$.
        \item \emph{Regularization modulus.} For $\alpha>0$, $\Lambda^{\mathrm{pt}}_{\Omega_\alpha}(R)\leq\tau\Delta_\alpha$ with $\Delta_\alpha:=\frac{\mu_{\min}^{1-\alpha}-1}{\alpha(\alpha-1)}$, and $\Delta_\alpha\leq\frac{1}{\alpha(1-\alpha)}$ for $0<\alpha<1$. For $\alpha\leq0$,
        \begin{equation}
            \label{eq:alpha_modulus}
            \Lambda^{\mathrm{pt}}_{\Omega_\alpha}(R)\ \leq\ \inf_{0<\varepsilon\leq1}\Big\{\varepsilon R+\tau\,\frac{1-\varepsilon^\alpha}{\alpha(1-\alpha)}\Big\}
            =\begin{cases}\Theta\big(\tau^{\frac{1}{1-\alpha}}R^{\frac{-\alpha}{1-\alpha}}\big)&\alpha<0,\\ \Theta\big(\tau\log(R/\tau)\big)&\alpha=0,\end{cases}
        \end{equation}
        the fraction read as $\log(1/\varepsilon)$ at $\alpha=0$, and these rates are attained. Hence the modulus is bounded in $R$ if and only if $\alpha>0$.
    \end{enumerate}

